import {icon} from './icons.js';
import {createLaura} from './laura.js';
import * as Data from './performance-data.js';
import {emptyOrganization,normalizeOrganization,activeOrganization,organizationMap,organizationHub,organizationOverview,createOrganizationItem,updateOrganizationItem,archiveOrganizationItem} from './organization.js';
import {emptyWorkflow,normalizeWorkflow,renderPersonalWorkflows,createPersonalItem,togglePersonalItem} from './personal-workflows.js';
import {emptyProfile,normalizeProfile,profileReady,profileRoleLabel,readProfile,onboardingForm,identityStrip,personalHeading,applyProfileGoal} from './onboarding-profile.js';
import {renderPersonalSection} from './personal-sections.js';
import {buildActivityReport,renderActivityReport,renderActivityReportSetup,activityReportCsv,activityReportEmail,activityReportHtml,reportsForCompany,reportCompanyKey} from './activity-report.js';
import {renderStaffingInsights,renderBuLinkedDeals,clientStack} from './staffing-insights.js';
import {renderFinanceCalculator,saveFinanceRecord,removeFinanceRecord,normalizeFinanceRecords,syncFinanceSalaryMode,calculateFinanceRecord} from './finance-calculator.js';
import {renderTerritoryCompass,renderTeamPortfolios,renderHandoffFlow} from './territory-workflow.js';

const {CITIES,BUS,MEMBERS,STAGES,DEALS,ACTIVITIES,WEEKLY_ACTIVITY,pct,scope,total,sum}=Data;
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Math.round(n).toLocaleString('fr-FR');
const money=n=>n>=1000?`${(n/1000).toLocaleString('fr-FR',{maximumFractionDigits:2})} M€`:`${n.toLocaleString('fr-FR',{maximumFractionDigits:1})} k€`;
const percent=(a,b)=>`${pct(a,b)} %`;
const bu=id=>BUS.find(b=>b.id===id);
const member=id=>MEMBERS.find(m=>m.id===id);
const GOAL=()=>({...Data.GOAL_2026,actual:Data.GOAL_2026?.completed??16});
const WEEK=()=>Data.WEEK_2026;
const INVOICES=()=>Data.INVOICES;
const avatarList=['claire-vasseur','nathalie-vidal','karim-delorme','sophie-ledran','julien-morvan','malik-ferhat','pierre-lavigne','lea-bonnard','julie-marchand','marc-aubriot','anne-sophie-verdier','paul-ferrer'];
const avatarMap=Object.fromEntries(MEMBERS.map((m,i)=>[m.id,avatarList[i%avatarList.length]]));
const avatar=(id,alt='')=>`<img class="avatar" src="assets/avatars/${avatarMap[id]||'claire-vasseur'}.svg" alt="${esc(alt||member(id)?.name||'Portrait')}">`;
const accountLogos={Altiver:'altiver-industries',Hélios:'groupe-helios',NovaSanté:'novasante'};
const accountLogo=name=>accountLogos[name]?`<img class="account-logo" src="assets/client-logos/${accountLogos[name]}.svg" alt="">`:'';
const roleAvatars={direction:'pierre-lavigne',manager:'anne-sophie-verdier',sales:'claire-vasseur'};
const roleNames={direction:'Direction · admin',manager:'Responsable d’agence',sales:'Business Manager'};
const userNames={direction:'Pierre Lavigne',manager:'Anne-Sophie Verdier',sales:'Nora Benali'};
const saved=(()=>{try{return JSON.parse(localStorage.getItem('bellum-white-commercial-v1'))||{}}catch{return {}}})();
const state={role:'direction',mode:'scenario',organization:emptyOrganization(),personalWorkflows:emptyWorkflow(),profile:emptyProfile(),personalSpaces:{},profileEditing:false,agendaDay:'',activitySeries:'all',activityDay:'',adminSub:'map',adminView:'performance',reportPeriod:'week',reportSeries:'all',reportOwner:'all',reportPreview:false,reportActiveId:null,reports:[],scenarioSeries:'all',scenarioDay:2,annualSeries:'all',annualPlan:null,orgCity:'all',orgAgency:'all',orgUnit:'all',orgEditing:null,city:'all',bu:'all',teamTab:'vue',teamSub:'objectifs',activityHour:'',pilotSection:'cockpit',pipeStage:'',dayTab:'priorites',mapCity:'Paris',mapBu:'all',assignments:{},outcomes:{},transmissions:[],invoiceNotes:{},financeRecords:[],financeSelectedId:null,...saved};
state.organization=normalizeOrganization(state.organization);
state.personalWorkflows=normalizeWorkflow(state.personalWorkflows);
state.profile=normalizeProfile(state.profile);
state.personalSpaces=state.personalSpaces&&typeof state.personalSpaces==='object'&&!Array.isArray(state.personalSpaces)?state.personalSpaces:{};
state.reports=Array.isArray(state.reports)?state.reports.filter(r=>r&&typeof r.id==='string'&&Array.isArray(r.rows)&&r.totals).slice(-20):[];
state.financeRecords=normalizeFinanceRecords(state.financeRecords);
if(!reportsForCompany(state.reports,state.profile.companyName).some(r=>r.id===state.reportActiveId))state.reportActiveId=null;
if(!['choose','scenario','personal'].includes(state.mode))state.mode='scenario';
if(state.mode==='choose'&&!saved.entryExperienceV14&&!state.profile.companyName)state.mode='scenario';
state.entryExperienceV14=true;
if(!Object.hasOwn(roleNames,state.role))state.role='sales';
if(state.mode==='personal')state.role=state.profile.jobRole||'sales';
let drawer=null,mobileMenu=false,closeToken=0,focusLocalItem=null;
const dayNav=[['today','Ma journée','sun'],['agenda','Mon agenda','calendar'],['team','Équipe','users'],['pilotage','Pilotage','columns']];
const teamTabs=[['vue','Vue d’ensemble'],['objectifs','Objectifs & affaires'],['plans','Plans'],['recherches','Recherches'],['activite','Activité'],['administration','Carte & agences']];
const pilotTabs=[['cockpit','Cockpit'],['pipe','Affaires en cours'],['staffing','Staffing'],['finance','Finance']];
function route(){let [name,query]=(location.hash.slice(1)||'today').split('?');return {name:dayNav.some(([id])=>id===name)?name:'today',params:new URLSearchParams(query||'')}}
function applyRoute(){let r=route();if(r.name==='team'&&state.role==='sales'&&state.mode==='scenario'){history.replaceState(null,'','#today');r=route()}if(r.params.has('tab'))state.teamTab=teamTabs.some(([id])=>id===r.params.get('tab'))?r.params.get('tab'):'vue';if(r.name==='pilotage')state.pilotSection=r.params.has('section')&&pilotTabs.some(([id])=>id===r.params.get('section'))?r.params.get('section'):'cockpit';if(state.mode==='scenario'&&r.params.has('city')&&CITIES.some(c=>c.name===r.params.get('city'))){state.mapCity=r.params.get('city');state.mapBu='all';state.city=r.params.get('city');state.bu='all'}if(state.mode==='scenario'&&r.params.has('bu')&&BUS.some(b=>b.id===r.params.get('bu'))){state.mapBu=r.params.get('bu');state.bu=r.params.get('bu')}if(state.mode==='scenario'&&state.role!=='direction'&&state.teamTab==='administration'){state.teamTab='vue';if(r.name==='team'){history.replaceState(null,'','#team?tab=vue');r=route()}}return r.name}
const spaceKey=companyName=>`company:${reportCompanyKey(companyName)}`;
const financeWorkspaceKey=()=>state.mode==='personal'?(reportCompanyKey(state.profile.companyName)?spaceKey(state.profile.companyName):''):'example:groupe-sillage';
const financePeople=()=>state.mode==='personal'?activeOrganization(state.organization).people:MEMBERS;
const financeOptions=()=>({workspaceKey:financeWorkspaceKey(),people:financePeople(),role:state.role,selectedId:state.financeSelectedId});
const financeLab=()=>`<div class="finance-lab">${renderFinanceCalculator(state.financeRecords,financeOptions())}</div>`;
const financeLauraContext=()=>state.role==='direction'?{records:normalizeFinanceRecords(state.financeRecords).filter(record=>record.workspaceKey===financeWorkspaceKey()),people:financePeople(),selectedId:state.financeSelectedId,workspaceKey:financeWorkspaceKey()}:null;
const currentSpace=()=>({profile:state.profile,organization:state.organization,personalWorkflows:state.personalWorkflows,orgCity:state.orgCity,orgAgency:state.orgAgency,orgUnit:state.orgUnit});
function save(){try{if(state.mode==='personal'&&reportCompanyKey(state.profile.companyName))state.personalSpaces[spaceKey(state.profile.companyName)]=currentSpace();localStorage.setItem('bellum-white-commercial-v1',JSON.stringify(state))}catch{}}
function navigate(name,query=''){drawer=null;mobileMenu=false;let hash=`#${name}${query?'?'+query:''}`;if($('#page-scroll'))$('#page-scroll').scrollTop=0;if(location.hash===hash)render(false);else location.hash=hash}
function btn(label,action,cls='',attrs=''){return `<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`}
function pageGuidance(){
  const active=route().name,local=state.mode==='personal';
  let copy='';
  if(state.mode==='choose')copy='Définissez votre entreprise et votre rôle pour organiser les vues, puis ajoutez vos agences et votre équipe.';
  else if(active==='today')copy=local
    ?'Votre profil fixe le périmètre. Ajoutez des actions, rendez-vous et activités pour construire votre journée et suivre votre cap.'
    :state.dayTab==='flux'
      ?state.role==='sales'?'Suivez séparément vos e-mails, approches LinkedIn et rendez-vous, puis ouvrez les affaires qui demandent une suite.':'Choisissez un canal et un jour pour lire l’activité, puis ouvrez l’affaire liée à un échange.'
      :state.role==='sales'?'Commencez par vos affaires à reprendre, préparez le prochain rendez-vous et consignez la suite sur chaque dossier.':'Commencez par les affaires à reprendre, puis ouvrez chaque dossier pour attribuer ou dater la prochaine action.';
  else if(active==='agenda')copy=local
    ?'Ajoutez vos rendez-vous et actions datées. Les éléments saisis apparaissent ici selon le jour choisi.'
    :'Ouvrez un rendez-vous pour préparer le compte. Après l’échange, consignez la prochaine étape dans l’affaire liée.';
  else if(active==='team'){
    const guides=local?{
      vue:'Vos agences, équipes et personnes viennent de votre espace. Les résultats attendent des actions et objectifs saisis.',
      objectifs:'Fixez les objectifs par personne ou par équipe, puis comparez-les aux réalisations enregistrées.',
      plans:'Répartissez les actions et leurs échéances. Chaque plan reste relié à la personne et au périmètre choisis.',
      recherches:'Vos expertises et secteurs déclarés cadrent la recherche. Vérifiez le besoin et son contact avant de créer une affaire.',
      activite:'Les actions saisies alimentent le journal. Filtrez par canal ou par jour pour retrouver leur détail.',
      administration:state.adminSub==='report'?'Choisissez une période et un périmètre, puis générez un rapport consultable et exportable depuis cet appareil.':'Créez vos agences, choisissez leur ville, puis ajoutez équipes, business units et personnes. La carte suit cette structure.'
    }:{
      vue:'La carte, les portefeuilles et les passations partagent le même périmètre. Ouvrez une ville ou un commercial pour voir les dossiers.',
      objectifs:'Comparez les contrats signés aux objectifs par BU, puis ouvrez une affaire pour vérifier sa prochaine étape.',
      plans:'Les échéances sont regroupées par dossier et responsable. Ouvrez une affaire pour consigner ou attribuer la suite.',
      recherches:'Une piste doit être qualifiée avant d’entrer dans le pipe. Ouvrez les affaires liées quand elles existent.',
      activite:'Choisissez une heure pour filtrer les interactions. Le journal indique le compte, la personne et le dossier quand ils sont connus.',
      administration:'Choisissez une ville sur la carte puis une BU. Ses affaires, responsables et factures s’affichent sur le même périmètre.'
    };
    copy=guides[state.teamTab]||guides.vue;
  } else if(active==='pilotage'){
    const guides=local?{
      cockpit:'Vos objectifs et vos activités alimentent cette vue au fur et à mesure de vos saisies. Ajustez le périmètre pour lire votre équipe.',
      pipe:'Consignez les prochaines actions. Les étapes et montants des affaires apparaîtront après connexion d’une source commerciale.',
      staffing:'La structure des équipes est visible ici. Les besoins et disponibilités apparaîtront lorsqu’une source de staffing sera reliée.',
      finance:'La direction peut saisir un coût et une marge par commercial. Les échéances et calculs locaux restent distincts de la facturation non reliée.'
    }:{
      cockpit:'Comparez contrats signés, objectif et pipe ouvert. Les graphiques montrent les volumes et la cadence du périmètre choisi.',
      pipe:'Choisissez une étape pour filtrer les affaires, puis ouvrez un dossier pour voir son responsable et sa prochaine action.',
      staffing:'Repérez les besoins sans profil et ouvrez les dossiers concernés pour préparer une présentation.',
      finance:state.role==='direction'?'Signé, facturé et encaissé sont distincts. Renseignez les coûts par commercial pour calculer la contribution mensuelle.':'Signé, facturé et encaissé sont distincts. Ouvrez une facture pour vérifier son échéance et l’affaire liée.'
    };
    copy=guides[state.pilotSection]||guides.cockpit;
  }
  return `<div class="page-guidance" role="note"><span class="page-guidance-label">Comment lire cette page</span><p>${esc(copy)}</p></div>`;
}
function heading(kicker,title,copy,action=''){return `<header class="heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${copy}</p></div>${action?`<div class="heading-actions">${action}</div>`:''}</header>${pageGuidance()}`}

function section(title,desc='',extra=''){return `<div class="section-title"><div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${extra}</div>`}
function toast(message){let el=document.createElement('div');el.className='toast';el.textContent=message;$('#toast-root').append(el);setTimeout(()=>el.remove(),3600)}
function visibleBus(){return state.role==='sales'?scope('Paris','gc'):state.role==='manager'?scope('Paris',state.bu==='gc'||state.bu==='data'?state.bu:'all'):scope(state.city,state.bu)}
function visibleDeals(rows=visibleBus()){let ids=new Set(rows.map(b=>b.id));return DEALS.filter(d=>ids.has(d.bu)&&(state.role!=='sales'||owner(d)==='nora'||!owner(d)||(state.transmissions||[]).some(x=>x.to==='nora'&&x.dealId===d.id)))}
function scopeName(rows=visibleBus()){if(state.role==='sales')return 'Paris · Grands comptes';if(state.role==='manager')return 'Agence Paris'+(state.bu!=='all'?` · ${bu(state.bu)?.name}`:'');return state.bu!=='all'?`${bu(state.bu)?.name} · ${bu(state.bu)?.city}`:state.city!=='all'?`Toutes les BU · ${state.city}`:'Groupe · France'}
function owner(d){return state.assignments[d.id]===undefined?d.owner:state.assignments[d.id]}
function age(d){return state.outcomes[d.id]&&state.outcomes[d.id].type!=='sans_reponse'?0:d.age}
function next(d){return ({rdv:'Préparer le rendez-vous',besoin:'Proposer un profil',reponse:'Confirmer la prochaine étape',sans_reponse:'Relancer demain'})[state.outcomes[d.id]?.type]||d.next}
function dueISO(d){let found=d.due.match(/^(\d+)\s+(nov|déc)/);return state.outcomes[d.id]?.due||(found?`2026-${found[2]==='déc'?'12':'11'}-${found[1].padStart(2,'0')}`:'2026-11-27')}
function shortDate(v){try{return new Intl.DateTimeFormat('fr-FR',{day:'numeric',month:'short'}).format(new Date(`${v}T12:00:00Z`))}catch{return v}}
function todayISO(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function editableDue(value){return value&&value>=todayISO()?value:todayISO()}
function filters(){let rows=visibleBus();if(state.role==='sales')return `<div class="scope-bar"><span class="scope-label">PÉRIMÈTRE</span><strong>${scopeName(rows)}</strong><span class="scope-asof">Novembre 2026</span></div>`;return `<div class="scope-bar"><span class="scope-label">PÉRIMÈTRE</span>${state.role==='direction'?`<label class="select-wrap"><span class="sr-only">Ville</span><select class="select" data-change="city"><option value="all">France entière</option>${CITIES.map(c=>`<option value="${c.name}" ${state.city===c.name?'selected':''}>${c.name}</option>`).join('')}</select></label>`:''}<label class="select-wrap"><span class="sr-only">Business unit</span><select class="select" data-change="bu"><option value="all">Toutes les BU</option>${BUS.filter(b=>state.role==='direction'?(state.city==='all'||b.city===state.city):b.city==='Paris').map(b=>`<option value="${b.id}" ${state.bu===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label><span class="scope-asof">Novembre 2026</span></div>`}
function sidebar(active){
  const personal=state.mode==='personal',choose=state.mode==='choose';
  const workspace=personal?(profileReady(state.profile)?esc(state.profile.companyName):'Mon espace local'):choose?'Choisir un espace':'Groupe Sillage';
  const detail=personal?(profileReady(state.profile)?`Espace de ${esc(state.profile.firstName)}`:'Votre contexte à préciser'):choose?'Aucun jeu de données actif':'Vue commerciale';
  const roleDetail=choose?'Fonction non renseignée':personal?profileRoleLabel(state.profile.jobRole):roleNames[state.role];
  return `<aside class="sidebar glass ${mobileMenu?'open':''}"><div class="brand"><img src="assets/bellum.svg" alt=""><span>bellum<span class="brand-ai">AI</span></span></div><div class="workspace"><span class="workspace-monogram">${personal?'M':choose?'B':'S'}</span><div><strong>${workspace}</strong><small>${detail}</small></div></div><nav class="nav-list" aria-label="Navigation principale"><div class="nav-caption">ESPACE DE TRAVAIL</div><button type="button" class="nav-parent active" data-action="parent-nav">${icon('sun')}<span>Ma journée</span>${icon('arrow')}</button><div class="nav-children">${dayNav.filter(([id])=>state.mode!=='scenario'||state.role!=='sales'||id!=='team').map(([id,label,glyph])=>`<button type="button" class="nav-child ${active===id?'active':''}" data-route="${id}" ${active===id?'aria-current="page"':''}>${icon(glyph)}<span>${id==='today'?'Vue du jour':label}</span></button>`).join('')}</div></nav><div class="side-footer"><button type="button" class="profile-button" data-action="${state.mode==='scenario'?'role-picker':choose?'mode-start-personal':'profile-edit'}" aria-label="${state.mode==='scenario'?'Choisir une fonction':choose?'Configurer mon profil':'Modifier mon profil'}">${state.mode==='scenario'?`<img class="avatar profile-avatar" src="assets/avatars/${roleAvatars[state.role]}.svg" alt="Portrait">`:`<span class="avatar profile-avatar org-profile-avatar" aria-hidden="true">${profileReady(state.profile)?esc(state.profile.firstName.slice(0,2).toUpperCase()):'VP'}</span>`}<span><strong>${state.mode==='scenario'?userNames[state.role]:choose?'Commencer':profileReady(state.profile)?esc(state.profile.firstName):'Votre profil'}</strong><small>${roleDetail}</small></span>${icon('down')}</button></div></aside>`;
}
function topbar(active){
  return `<header class="topbar glass"><button type="button" class="mobile-toggle icon-button" data-action="mobile-toggle" aria-label="Afficher le menu">${icon('menu')}</button><div class="top-context"><span>BellumAI</span><span class="top-divider">/</span><strong>Ma journée</strong>${active==='today'?'':`<span class="top-divider">/</span><strong>${dayNav.find(([id])=>id===active)?.[1]}</strong>`}</div><div class="top-actions"><label class="role-select-wrap org-mode-select"><span class="sr-only">Choisir le jeu de données</span><select class="select role-select" data-change="mode"><option value="choose" ${state.mode==='choose'?'selected':''}>Choisir un espace</option><option value="personal" ${state.mode==='personal'?'selected':''}>Mon espace local</option><option value="scenario" ${state.mode==='scenario'?'selected':''}>Explorer l’exemple</option></select></label>${state.mode==='scenario'?`<label class="role-select-wrap"><span class="sr-only">Changer de fonction</span><select class="select role-select" data-change="role">${Object.entries(roleNames).map(([id,label])=>`<option value="${id}" ${state.role===id?'selected':''}>${label}</option>`).join('')}</select></label>`:''}</div></header>`;
}
let lastRenderedRoute='';
function shell(active,body){
  const note=state.mode==='scenario'?'Données d’exemple arrêtées au 25 nov. 2026 · non synchronisées':state.mode==='personal'?'Données conservées sur cet appareil · CRM et ATS non connectés':'Choisissez votre espace ; les données de l’exemple restent séparées des vôtres.';
  const routeKey=location.hash||'#today',enter=routeKey!==lastRenderedRoute;lastRenderedRoute=routeKey;
  return `<div class="app ${mobileMenu?'nav-open':''}">${mobileMenu?'<button class="mobile-shade" data-action="mobile-toggle" aria-label="Fermer le menu"></button>':''}${sidebar(active)}<div class="app-main">${topbar(active)}<main class="page ${enter?'route-enter':''}" id="page-scroll"><div class="preview-note" role="note">${note}</div>${body}<footer class="page-footer">BellumAI</footer></main></div></div>`;
}

function annualChart(){
  const g=GOAL(),monthly=g.monthlyStarts.filter(x=>x.count!==null),points=[0];
  let run=0;for(const item of monthly){run+=item.count;points.push(run)}
  const max=Math.max(g.target,run)+2,W=760,H=190,L=28,R=18,T=16,B=27;
  const xy=(v,i)=>[L+(W-L-R)*i/12,T+(H-T-B)*(1-v/max)];
  const actual=points.map((v,i)=>xy(v,i).join(',')).join(' ');
  const targets=[0,...g.trajectory.map(x=>x.target)];
  const target=targets.map((v,i)=>xy(v,i).join(',')).join(' ');
  const mode=['all','actual','target'].includes(state.annualSeries)?state.annualSeries:'all';
  const showActual=mode!=='target',showTarget=mode!=='actual';
  return `<div class="chart-legend"><span><i class="legend-line solid"></i>Démarrages réalisés</span><span><i class="legend-line dashed"></i>Rythme cible</span></div><div class="series-filter annual-series" role="group" aria-label="Filtrer la trajectoire">${[['all','Les deux'],['actual','Réalisé'],['target','Cible']].map(([value,label])=>`<button type="button" data-action="annual-series" data-value="${value}" class="${mode===value?'active':''}" aria-pressed="${mode===value}">${label}</button>`).join('')}</div><svg class="goal-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${run} démarrages cumulés au 25 novembre sur ${g.target} visés à fin décembre"><defs><linearGradient id="goal-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#9b79c4" stop-opacity=".34"/><stop offset="100%" stop-color="#9b79c4" stop-opacity=".015"/></linearGradient><linearGradient id="goal-target-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#767080" stop-opacity=".19"/><stop offset="100%" stop-color="#767080" stop-opacity=".012"/></linearGradient></defs><line x1="${L}" y1="${xy(0,0)[1]}" x2="${W-R}" y2="${xy(0,0)[1]}" class="axis"/><line x1="${L}" y1="${xy(11,0)[1]}" x2="${W-R}" y2="${xy(11,0)[1]}" class="gridline"/><line x1="${L}" y1="${xy(22,0)[1]}" x2="${W-R}" y2="${xy(22,0)[1]}" class="gridline"/>${showTarget?`<polygon points="${target} ${xy(0,12)[0]},${xy(0,0)[1]} ${L},${xy(0,0)[1]}" class="goal-target-area"/><polyline points="${target}" class="goal-target"/>`:''}${showActual?`<polygon points="${actual} ${xy(0,points.length-1)[0]},${xy(0,0)[1]} ${L},${xy(0,0)[1]}" class="goal-area"/><polyline points="${actual}" class="goal-actual"/><circle cx="${xy(run,points.length-1)[0]}" cy="${xy(run,points.length-1)[1]}" r="5" class="goal-end"><title>25 novembre : ${run} démarrages réalisés</title></circle>`:''}</svg><div class="goal-axis" aria-hidden="true"><span>Jan</span><span>Avr</span><span>Juil</span><span>Oct</span><span>Déc</span></div><div class="chart-bottom"><span>Démarrages cumulés · suivi des démarrages</span><span>Dernière observation : 25 nov.</span></div><button class="text-button" type="button" data-action="pilot-pipe">Voir les affaires en cours →</button>`;
}
function annualHero(){let g=GOAL(),remaining=Math.max(0,g.target-g.actual);return `<section class="glass hero-dashboard"><div class="hero-copy"><div class="eyebrow">CAP ANNUEL · DÉMARRAGES</div><div class="hero-number"><strong>${g.actual}</strong><span>/ ${g.target}</span></div><h2>${remaining} démarrages restent à sécuriser.</h2><p>Les affaires en cours ont chacune une prochaine étape. Leur valeur n’est pas un démarrage acquis.</p><button class="text-button" data-action="pilot-pipe">Voir les affaires à faire avancer ${icon('arrow')}</button></div><div class="hero-chart">${annualChart()}</div></section>`}
function weekModel(){let w=WEEK(),target=Object.fromEntries(w.metrics.map(m=>[m.id,m.target])),actual=Object.fromEntries(w.metrics.map(m=>[m.id,m.actual]));return {target,actual,daily:w.reach,source:w.targetBasis};}
function metricBar(label,actual,target,unit,kind){return `<div class="metric-tile" data-metric="${kind}"><div class="metric-tile-top"><span>${label}</span><strong>${fmt(actual)} <small>/ ${fmt(target)}</small></strong></div><div class="bar-track"><span class="bar-fill" style="width:${Math.min(100,pct(actual,target))}%"></span></div><div class="metric-tile-bottom"><span>${fmt(Math.max(0,target-actual))} ${unit} à faire</span><span>${percent(actual,target)}</span></div></div>`}
function weekRhythm(){let {target,actual,source}=weekModel(),metrics=[['E-mails déclarés','emails','e-mails'],['Approches LinkedIn','linkedin','approches'],['RDV déclarés','meetings','RDV'],['Besoins qualifiés','needs','besoins']];return `<section class="glass card activity-card">${section('Cadence du groupe · 23–27 nov.','Activité suivie et cibles de la semaine',`<button class="text-button" data-action="day-tab" data-value="flux">Voir le journal ${icon('arrow')}</button>`)}<div class="activity-metrics">${metrics.map(([name,key,unit])=>metricBar(name,actual[key]||0,target[key]||1,unit,key)).join('')}</div><p class="panel-footnote">${esc(source)} · cumul au mercredi 25 novembre.</p></section>`}
function personalRhythm(){let actual=Data.MEMBER_WEEK?.nora||{},target=Data.PERSONAL_TARGETS?.nora||{};let items=[['E-mails déclarés','emails','e-mails'],['Approches LinkedIn','linkedin','approches'],['RDV déclarés','meetings','RDV'],['Besoins qualifiés','needs','besoins']];return `<section class="glass card activity-card personal-cadence">${section('Ma cadence · 23–27 nov.','Nora · données au 25 nov.',`<span class="person">${avatar('nora')}<span>Objectifs personnels</span></span>`)}<div class="activity-metrics">${items.map(([label,key,unit])=>metricBar(label,actual[key]||0,target[key]||1,unit,key)).join('')}</div><p class="panel-footnote">Cibles personnelles · 23–27 nov. E-mails et LinkedIn restent deux activités distinctes.</p></section>`}
function annualPlan(){
  const g=GOAL(),value=state.annualPlan&&typeof state.annualPlan==='object'&&!Array.isArray(state.annualPlan)?state.annualPlan:{};
  const valid=(n,min,max)=>Number.isInteger(n)&&n>=min&&n<=max;
  const target=g.target;
  const weeks=valid(value.weeks,1,52)?value.weeks:null;
  const rates=['reply','meeting','need','start'].every(key=>valid(value.rates?.[key],1,100))?value.rates:null;
  const emailShare=valid(value.emailShare,0,100)?value.emailShare:null;
  return {target,weeks,rates,emailShare,complete:!!(weeks&&rates&&emailShare!==null)};
}
function annualPlanField(label,name,value,min,max){
  return `<label class="annual-plan-field"><span>${label}</span><input name="${name}" inputmode="numeric" type="number" min="${min}" max="${max}" step="1" value="${value??''}"></label>`;
}
function reverseLadder(){
  const g=GOAL(),plan=annualPlan(),remaining=Math.max(0,plan.target-g.actual);
  const model=plan.complete?Data.deriveReversePlan({target:plan.target,completed:g.actual,weightedPipe:0,weeks:plan.weeks,rates:Object.fromEntries(Object.entries(plan.rates).map(([key,value])=>[key,value/100]))}):null;
  const steps=model?[['Sollicitations',model.touches],['Réponses',model.replies],['Rendez-vous',model.meetings],['Besoins',model.needs],['Démarrages',model.toCreate]]:[];
  const weekly=model?.perWeek.touches??0,emails=Math.ceil(weekly*(plan.emailShare??0)/100),linkedin=weekly-emails;
  const results=model?`<div class="workflow-ladder">${steps.map(([name,n],i)=>`<div class="workflow-step"><div class="workflow-label"><strong>${fmt(n)}</strong><span>${name}</span></div><div class="workflow-shape" style="--w:${Math.max(15,Math.round(Math.sqrt(n/(steps[0][1]||1))*100))}%"><span></span></div>${i?`<small>${percent(n,steps[i-1][1])} de l’étape précédente</small>`:`<small>Sur ${plan.weeks} ${plan.weeks===1?'semaine':'semaines'}</small>`}</div>`).join('')}</div><div class="workflow-conclusion"><strong>${fmt(weekly)} sollicitations par semaine</strong><span>${fmt(emails)} e-mails · ${fmt(linkedin)} approches LinkedIn. Cadence calculée d’après vos taux saisis ; les objectifs de la semaine restent distincts.</span></div>`:`<p class="body-copy annual-plan-empty">Renseignez votre horizon et vos taux pour calculer la cadence. Les ${fmt(remaining)} démarrages à sécuriser ne sont pas couverts par les affaires ouvertes.</p>`;
  return `<section class="glass card workflow-card">${section('Du cap à la cadence',`${fmt(g.actual)} démarrages réalisés sur ${fmt(g.target)} · ${fmt(remaining)} à sécuriser`)}${results}<details class="annual-plan-editor" id="annual-plan-editor"><summary>${model?'Modifier le plan':'Calculer la cadence'}<span aria-hidden="true">⌄</span></summary><form data-plan-form><div class="annual-plan-fields">${annualPlanField('Horizon · semaines','weeks',plan.weeks,1,52)}${annualPlanField('Réponses / sollicitations · %','reply',plan.rates?.reply,1,100)}${annualPlanField('RDV / réponses · %','meeting',plan.rates?.meeting,1,100)}${annualPlanField('Besoins / RDV · %','need',plan.rates?.need,1,100)}${annualPlanField('Démarrages / besoins · %','start',plan.rates?.start,1,100)}${annualPlanField('Part e-mail · %','emailShare',plan.emailShare,0,100)}</div><p class="annual-plan-note">Saisissez vos taux et l’horizon. Cette cadence de travail reste distincte des objectifs hebdomadaires enregistrés.</p><button type="submit" class="btn btn-primary">Enregistrer la cadence</button></form></details></section>`;
}
function signals(rows=visibleBus()){let d=visibleDeals(rows).filter(x=>state.role!=='sales'||owner(x)==='nora'),late=d.filter(x=>age(x)>=11||!owner(x)),inv=INVOICES().filter(x=>rows.some(b=>b.id===x.bu)&&x.status==='overdue'&&(state.role!=='sales'||x.owner==='nora')),m=weekModel(),meetingTarget=state.role==='sales'?Data.PERSONAL_TARGETS?.nora?.meetings:m.target.meetings,meetingActual=state.role==='sales'?Data.MEMBER_WEEK?.nora?.meetings:m.actual.meetings,missing=Math.max(0,(meetingTarget||0)-(meetingActual||0)),scopeHasTarget=state.role==='sales'||state.role==='direction'&&state.city==='all'&&state.bu==='all',prepared=eventRows(rows).filter(e=>e.status==='upcoming'&&e.date>=todayISO()&&['Client','Entretien'].includes(e.kind)).length;return `<div class="signal-strip" aria-label="Points à surveiller"><button data-action="focus-actions"><strong>${late.length}</strong><span>affaire${late.length>1?'s':''} à reprendre</span><small>${state.role==='sales'?'sans échange récent':'responsable ou échange'}</small></button><button data-action="route-agenda"><strong>${scopeHasTarget?missing:prepared}</strong><span>${scopeHasTarget?'RDV sous la cible hebdo':'RDV clients à préparer'}</span><small>${scopeHasTarget?'au 25 nov. · cible du 23–27':'sur ce périmètre'}</small></button><button data-action="pilot-finance"><strong>${money(sum(inv,'amount')/1000)}</strong><span>de factures en retard</span><small>${inv.length} facture${inv.length>1?'s':''} · encaissé distinct du signé</small></button></div>`}
function taskRows(rows=visibleBus(),limit=5){let d=visibleDeals(rows).filter(x=>state.role!=='sales'||owner(x)==='nora').filter(x=>!owner(x)||age(x)>=11||dueISO(x)<='2026-11-27').sort((a,b)=>(!owner(a)?-1:1)-(!owner(b)?-1:1)||age(b)-age(a));return d.slice(0,limit).map((x,i)=>`<button class="task-item" type="button" data-action="deal" data-id="${x.id}"><span class="task-index">${String(i+1).padStart(2,'0')}</span><span class="task-main"><strong>${esc(next(x))}</strong><small>${esc(x.account)} · ${esc(bu(x.bu).name)} · ${owner(x)?esc(member(owner(x))?.name):'à attribuer'}</small></span><span class="task-meta"><b class="${age(x)>=11||!owner(x)?'risk':''}">${!owner(x)?'À répartir':age(x)>=11?`${age(x)} j sans échange`:shortDate(dueISO(x))}</b><small>${money(x.amount)} de pipe</small></span>${icon('arrow')}</button>`).join('')||'<p class="body-copy">Aucun dossier prioritaire sur ce périmètre.</p>'}
function dailyBarcode(rows=visibleBus()){
  const arr=weekModel().daily,series=['email','linkedin'].includes(state.scenarioSeries)?state.scenarioSeries:'all',index=Math.max(0,Math.min(arr.length-1,Number(state.scenarioDay)||0)),selected=arr[index];
  const count=(d,key)=>d[key]===null||d[key]===undefined?null:Number(d[key]),email=d=>count(d,'emails'),linkedin=d=>count(d,'linkedin'),value=d=>series==='email'?email(d):series==='linkedin'?linkedin(d):email(d)===null||linkedin(d)===null?null:email(d)+linkedin(d),max=Math.max(1,...arr.flatMap(d=>[email(d)||0,linkedin(d)||0]));
  const linked=index===2?(Data.TOUCHPOINTS||[]).filter(t=>rows.some(b=>b.id===t.bu)&&(state.role!=='sales'||t.owner==='nora')).map(t=>({touch:t,deal:visibleDeals(rows).find(d=>d.account===t.account)})).filter(item=>item.deal).slice(0,3):[];
  return `<div class="series-filter" role="group" aria-label="Filtrer les canaux de prospection">${[['all','Les deux canaux'],['email','E-mails'],['linkedin','LinkedIn']].map(([id,label])=>`<button type="button" class="${series===id?'active':''}" data-action="scenario-series" data-value="${id}" aria-pressed="${series===id}">${label}</button>`).join('')}</div><div class="day-barcode" role="group" aria-label="Prospection par jour et canal">${arr.map((d,i)=>`<button type="button" class="barcode-day ${i===index?'active':''}" data-action="scenario-day" data-value="${i}" aria-pressed="${i===index}" aria-label="${esc(d.day)}, ${email(d)??'non renseigné'} e-mails, ${linkedin(d)??'non renseigné'} approches LinkedIn"><span class="barcode-pair">${series!=='linkedin'&&email(d)!==null?`<i class="barcode-line email" style="height:${email(d)?Math.max(7,Math.round(email(d)/max*105)):0}px;--delay:${i*55}ms"></i>`:''}${series!=='email'&&linkedin(d)!==null?`<i class="barcode-line linkedin" style="height:${linkedin(d)?Math.max(7,Math.round(linkedin(d)/max*105)):0}px;--delay:${i*55+45}ms"></i>`:''}</span><small>${esc(d.day||['Lun','Mar','Mer','Jeu','Ven'][i])}</small><b>${value(d)===null?'—':fmt(value(d))}</b></button>`).join('')}</div><div class="scenario-day-detail"><div><strong>${esc(['Lundi 23','Mardi 24','Mercredi 25','Jeudi 26','Vendredi 27'][index])} novembre</strong><small>Activité déclarée pour ce jour</small></div><div class="scenario-day-metrics"><span>E-mails <strong>${email(selected)===null?'Non renseigné':fmt(email(selected))}</strong></span><span>LinkedIn <strong>${linkedin(selected)===null?'Non renseigné':fmt(linkedin(selected))}</strong></span><span>RDV déclarés <strong>${selected.meetings===null?'Non renseigné':fmt(selected.meetings||0)}</strong></span></div>${linked.length?`<div class="scenario-day-links"><small>Comptes sollicités ce jour</small>${linked.map(({touch,deal})=>`<button type="button" class="text-button" data-action="deal" data-id="${deal.id}">${esc(touch.account)} · ${esc(touch.title)} →</button>`).join('')}</div>`:'<p class="panel-footnote">Aucun compte rattaché à cette journée.</p>'}</div><p class="panel-footnote">Données arrêtées au 25 nov. · e-mails et approches LinkedIn restent distincts. Jeudi et vendredi non renseignés.</p>`;
}
function activityStream(rows=visibleBus(),hour=''){let entries=[...(state.transmissions||[]).filter(x=>rows.some(b=>b.id===DEALS.find(d=>d.id===x.dealId)?.bu)).map(x=>{let d=DEALS.find(d=>d.id===x.dealId);return {time:'Maintenant',person:x.by,action:`Transmis à ${member(x.to)?.name}`,account:d.account,bu:d.bu,type:'Passation',id:d.id}}),...Object.entries(state.outcomes).map(([id,o])=>{let d=DEALS.find(x=>x.id===id);return d?{time:'Maintenant',person:member(owner(d))?.name||'Équipe',action:o.label,account:d.account,bu:d.bu,type:'Suite',id}:null}).filter(Boolean),...Object.entries(state.invoiceNotes).map(([id,n])=>{let x=INVOICES().find(x=>x.id===id);return x?{time:'Maintenant',person:member(x.owner)?.name||'Équipe',action:`Relance facture ${id} consignée · avant ${shortDate(n.due)}`,account:x.account,bu:x.bu,type:'Finance',invoiceId:id}:null}).filter(Boolean),...(Data.TOUCHPOINTS||[]).filter(x=>rows.some(b=>b.id===x.bu)).map(x=>({time:x.when,person:member(x.owner)?.name||'À répartir',action:x.title,account:x.account,bu:x.bu,type:x.source,id:DEALS.find(d=>d.account===x.account&&d.bu===x.bu)?.id,invoiceId:x.link==='invoice'?INVOICES().find(i=>i.account===x.account&&i.bu===x.bu&&i.status==='overdue')?.id:null}))];if(state.role==='sales')entries=entries.filter(x=>x.person==='Nora Benali'||x.id&&visibleDeals(rows).some(d=>d.id===x.id));if(hour)entries=entries.filter(x=>x.time.startsWith(hour));return `<div class="timeline">${entries.map(x=>{const linked=!!(x.invoiceId||x.id),tag=linked?'button':'div';return `<${tag} class="timeline-item${linked?'':' timeline-static'}"${linked?` data-action="${x.invoiceId?'invoice':'deal'}" data-id="${esc(x.invoiceId||x.id)}"`:''}><time>${esc(x.time)}</time><span class="timeline-dot"></span><span><strong>${esc(x.action)}</strong><small>${esc(x.account)} · ${esc(x.person)} · ${esc(x.type)}</small></span>${linked?icon('arrow'):''}</${tag}>`}).join('')||'<p class="body-copy">Aucune activité documentée sur ce créneau et ce périmètre.</p>'}</div>`}
function pendingTransfers(rows){let ids=new Set(visibleDeals(rows).map(d=>d.id));let arr=(state.transmissions||[]).filter(x=>ids.has(x.dealId)&&(state.role!=='sales'||x.to==='nora'||x.by===userNames.sales));return arr.length?`<section class="glass card">${section('Passations de l’équipe','Une note, un responsable et une échéance sur chaque dossier')}${arr.slice(-3).reverse().map(x=>{let d=DEALS.find(d=>d.id===x.dealId);return `<button class="task-item" data-action="deal" data-id="${d.id}"><span class="task-main"><strong>${esc(d.account)} → ${esc(member(x.to)?.name)}</strong><small>${esc(x.note)}</small></span><b>${shortDate(x.due)}</b></button>`}).join('')}</section>`:''}
function todayPage(){
  const rows=visibleBus(),deals=visibleDeals(rows).filter(d=>state.role!=='sales'||owner(d)==='nora'),toResume=deals.filter(d=>!owner(d)||age(d)>=11),firstName=userNames[state.role]?.split(' ')[0]||'vous';
  const nextEvent=eventRows(rows).filter(e=>e.status==='upcoming'&&e.date>=todayISO()).sort((a,b)=>a.date.localeCompare(b.date)||a.start.localeCompare(b.start))[0];
  const line=state.role==='direction'?`Chez Groupe Sillage, ${toResume.length} affaire${toResume.length>1?'s':''} attend${toResume.length>1?'ent':''} un responsable ou un nouvel échange.`:state.role==='manager'?`Sur ${scopeName(rows)}, ${toResume.length} dossier${toResume.length>1?'s':''} à reprendre avec l’équipe.`:`Dans votre portefeuille, ${toResume.length} affaire${toResume.length>1?'s':''} à reprendre avant les prochains échanges.`;
  const intro=heading(`SEMAINE DU 23 AU 27 NOV. · ${scopeName(rows)}`,`Bonjour ${esc(firstName)}.`,line,btn('Demander à Laura','ask-laura','btn-quiet'));
  const tabs=`<div class="sub-tabs" aria-label="Ma journée"><button class="${state.dayTab==='priorites'?'active':''}" data-action="day-tab" data-value="priorites">À traiter</button><button class="${state.dayTab==='flux'?'active':''}" data-action="day-tab" data-value="flux">Prospection & activité</button></div>`;
  const focus=toResume[0];
  const lauraGlance=`<section class="glass card laura-glance">${section('Le point de Laura',focus?`${esc(focus.account)} · ${!owner(focus)?'responsable à nommer':`${age(focus)} jours sans échange au 25 nov.`}`:'Aucun dossier sans responsable ou sans échange récent',btn('Demander à Laura','ask-laura','btn-quiet'))}<p class="body-copy">${focus?`À faire : ${esc(next(focus))}. Retrouvez le contexte et attribuez la suite dans la fiche.`:'Laura peut résumer les prochains rendez-vous et les échéances de ce périmètre.'}</p>${focus?`<button type="button" class="text-button" data-action="deal" data-id="${focus.id}">Ouvrir ${esc(focus.account)} ${icon('arrow')}</button>`:''}</section>`;
  const nextDeal=deals.filter(d=>owner(d)).sort((a,b)=>Number(age(a)>=11)-Number(age(b)>=11)||dueISO(a).localeCompare(dueISO(b)))[0];
  const portfolioPeek=nextDeal?`<div class="priority-deal-follow"><span class="eyebrow">AFFAIRE À SUIVRE</span><button class="brief-item" type="button" data-action="deal" data-id="${nextDeal.id}"><span><strong>${accountLogo(nextDeal.account)}${esc(nextDeal.account)} · ${esc(nextDeal.stage)}</strong><small>${esc(next(nextDeal))} · ${shortDate(dueISO(nextDeal))} · ${money(nextDeal.amount)} de pipe</small></span>${icon('arrow')}</button></div>`:'';
  const appointment=nextEvent?`<section class="glass card">${section('Prochain rendez-vous',`${esc(nextEvent.account||nextEvent.kind)} · ${shortDate(nextEvent.date)} à ${nextEvent.start}`)}<button class="brief-item" data-action="event" data-id="${nextEvent.id}"><span><strong>${accountLogo(nextEvent.account)}${esc(nextEvent.title)}</strong><small>${esc(nextEvent.next)}</small><b class="agenda-followup">Préparer le rendez-vous</b></span>${icon('arrow')}</button>${portfolioPeek}</section>`:portfolioPeek?`<section class="glass card">${section('Affaire à suivre','Prochaine étape du portefeuille')}${portfolioPeek}</section>`:'';
  const priorities=`${localHero(rows)}${signals(rows)}<div class="content-grid lead-grid"><section class="glass card" id="priority-actions">${section('Actions prioritaires',`${toResume.length} dossier${toResume.length>1?'s':''} à reprendre · responsable, échange et prochaine date`)}<div class="task-list">${taskRows(rows,5)}</div></section>${appointment}</div>${pendingTransfers(rows)}${lauraGlance}`;
  const dealFocus=`<section class="glass card deal-focus-card">${section('Affaires à faire avancer',`${deals.length} affaires dans votre périmètre · les trois prochaines suites`,btn('Voir le pipeline','pilot-pipe','btn-quiet'))}<div class="task-list">${taskRows(rows,3)}</div></section>`;
  const personalMeetings=`<section class="glass card">${section('Rendez-vous à préparer','Le compte, l’enjeu et la prochaine étape')}${eventRows(rows).filter(e=>e.status==='upcoming'&&e.date>=todayISO()&&['Client','Entretien'].includes(e.kind)).slice(0,2).map(e=>`<button class="brief-item" data-action="event" data-id="${e.id}"><span><strong>${accountLogo(e.account)}${esc(e.account)} · ${shortDate(e.date)} à ${e.start}</strong><small>${esc(e.next)}</small></span>${icon('arrow')}</button>`).join('')||'<p class="body-copy">Aucun rendez-vous client à préparer.</p>'}</section>`;
  const cadence=state.role==='sales'?`<div class="content-grid lower">${personalRhythm()}${personalMeetings}</div>`:`<div class="content-grid lower"><section class="glass card">${section('Prospection · e-mails et LinkedIn','Activité du groupe par jour · 23–27 nov.')}${dailyBarcode(rows)}</section>${weekRhythm()}</div>`;
  const flux=`<div class="content-grid lead-grid">${dealFocus}<section class="glass card">${section('Dernières actions','Comptes, interlocuteurs et suites enregistrées')}${activityStream(rows)}</section></div>${cadence}`;
  const territoryAccess=state.role==='direction'?`<button type="button" class="territory-peek glass" data-action="go-map"><span class="territory-peek-icon">${icon('pin')}</span><span><small>FRANCE · PERFORMANCE COMMERCIALE</small><strong>Ouvrir la carte des agences</strong><em>Ville → business unit → affaires, équipe et factures</em></span>${icon('arrow')}</button>`:'';
  return `${intro}${filters()}${territoryAccess}${tabs}${state.dayTab==='flux'?flux:priorities}`;
}

function eventRows(rows=visibleBus()){let ids=new Set(rows.map(b=>b.id));return (Data.EVENTS||[]).filter(e=>ids.has(e.bu)&&(state.role!=='sales'||e.owner==='nora'||e.account==='Altiver'))}
function agendaPage(){
  const rows=visibleBus(),events=eventRows(rows),firstName=userNames[state.role]?.split(' ')[0]||'vous';
  const days=[['Lundi','2026-11-23','23'],['Mardi','2026-11-24','24'],['Mercredi','2026-11-25','25'],['Jeudi','2026-11-26','26'],['Vendredi','2026-11-27','27']];
  const clients=events.filter(e=>['Client','Entretien'].includes(e.kind)),upcoming=events.filter(e=>e.status==='upcoming'&&e.date>=todayISO()&&e.account&&['Client','Entretien'].includes(e.kind)),done=events.filter(e=>e.status==='done'&&e.account&&['Client','Entretien'].includes(e.kind));
  const summary=`<div class="agenda-summary"><div><span>RDV clients</span><strong>${clients.length}</strong><small>23–27 nov.</small></div><div><span>À préparer</span><strong>${upcoming.filter(e=>['Client','Entretien'].includes(e.kind)).length}</strong><small>sur les comptes du périmètre</small></div><div><span>Suites consignées</span><strong>${Object.keys(state.outcomes).filter(id=>visibleDeals(rows).some(d=>d.id===id)).length}</strong><small>dans les affaires</small></div></div>`;
  const week=`<section class="glass card agenda-card">${section('La semaine','Compte, enjeu et prochaine suite pour chaque créneau')}<div class="agenda-grid">${days.map(([name,date,day])=>`<div class="agenda-day ${date===todayISO()?'current':''}"><h3><small>${name}</small><strong>${day}</strong></h3>${events.filter(e=>e.date===date).sort((a,b)=>a.start.localeCompare(b.start)).map(e=>`<button type="button" class="agenda-event ${e.kind==='Client'||e.kind==='Entretien'?'client':''}" data-action="event" data-id="${e.id}"><time>${e.start}–${e.end}</time><strong>${esc(e.title)}</strong><span class="agenda-account">${accountLogo(e.account)}${esc(e.account||e.kind)}</span><small>${esc(e.next)}</small></button>`).join('')||'<p class="agenda-empty">Aucun rendez-vous prévu</p>'}</div>`).join('')}</div></section>`;
  const before=`<section class="glass card">${section('À préparer','Le compte et la question à poser avant l’échange')}${upcoming.slice(0,3).map(e=>`<button class="brief-item" data-action="event" data-id="${e.id}"><span><strong>${accountLogo(e.account)}${esc(e.account)} · ${shortDate(e.date)} à ${e.start}</strong><small>${esc(e.next)}</small><b class="agenda-followup">Préparer le RDV</b></span>${icon('arrow')}</button>`).join('')||'<p class="body-copy">Aucun rendez-vous client à préparer sur ce périmètre.</p>'}</section>`;
  const after=`<section class="glass card">${section('À consigner','Une décision, un responsable et une prochaine date')}${done.slice(0,3).map(e=>`<button class="brief-item" data-action="event" data-id="${e.id}"><span><strong>${accountLogo(e.account)}${esc(e.account)} · ${shortDate(e.date)}</strong><small>${esc(e.next)}</small><b class="agenda-followup">Consigner la suite</b></span>${icon('arrow')}</button>`).join('')||'<p class="body-copy">Aucune suite en attente de consignation.</p>'}</section>`;
  return `${heading('MA JOURNÉE / MON AGENDA',`${esc(firstName)}, vos rendez-vous`,`Groupe Sillage · ${clients.length} rendez-vous clients du 23 au 27 novembre.`)}${filters()}${summary}${week}<div class="content-grid lower">${before}${after}</div>`;
}

function teamNav(){return `<div class="team-tabs" role="navigation" aria-label="Vues d’équipe">${teamTabs.filter(([id])=>state.mode==='personal'||state.role==='direction'||id!=='administration').map(([id,name])=>`<button type="button" class="${state.teamTab===id?'active':''}" data-action="team-tab" data-value="${id}">${name}</button>`).join('')}</div>`}
function memberRows(rows){let ids=new Set(rows.map(b=>b.id)),members=MEMBERS.filter(m=>ids.has(m.bu));return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Commercial</th><th>BU</th><th>Signé · nov.</th><th>RDV · semaine</th><th>Affaires à reprendre</th><th></th></tr></thead><tbody>${members.map(m=>{let deals=DEALS.filter(d=>d.bu===m.bu&&owner(d)===m.id),late=deals.filter(d=>age(d)>=11).length,weekly=Data.MEMBER_WEEK?.[m.id]||{};return `<tr><td><div class="person">${avatar(m.id)}<span><strong>${esc(m.name)}</strong><small>${esc(m.role)}</small></span></div></td><td>${esc(bu(m.bu).name)}</td><td class="money">${money(m.signed)}</td><td>${weekly.meetings||0}</td><td class="${late?'risk':''}">${late}</td><td><button class="text-button" data-action="member" data-id="${m.id}">Voir ${icon('arrow')}</button></td></tr>`}).join('')}</tbody></table></div>`}
function progressByBu(rows){let max=Math.max(...rows.map(b=>b.target),1);return `<div class="staff-grid">${rows.map(b=>`<button class="staff-row" data-action="bu" data-id="${b.id}"><span><strong>${esc(b.name)}</strong><small>${esc(b.city)} · ${percent(b.signed,b.target)} de l’objectif</small></span><div class="staff-bar"><span style="width:${Math.max(3,b.signed/max*100)}%"></span><i style="left:${b.target/max*100}%"></i></div><b>${money(b.signed)} <small>/ ${money(b.target)}</small></b></button>`).join('')}</div><p class="panel-footnote">Trait : objectif mensuel. Barre : contrats signés de novembre, en k€.</p>`}
function dispatchCard(rows){let ids=new Set(rows.map(b=>b.id)),arr=(Data.DISPATCH||[]).filter(x=>ids.has(x.bu)&&(!owner(DEALS.find(d=>d.id===x.dealId))||x.kind==='Transmission interne'));if(!arr.length)return '';return `<section class="glass card dispatch-card">${section('Demandes à attribuer','Une demande ne doit pas rester sans destinataire',`<span class="tag tag-risk">${arr.filter(x=>!owner(DEALS.find(d=>d.id===x.dealId))).length} sans responsable</span>`)}<div class="dispatch-list">${arr.map(x=>{let d=DEALS.find(d=>d.id===x.dealId);return `<div class="dispatch-row"><span class="dispatch-kind">${esc(x.kind)}</span><span><strong>${esc(x.account)} · ${esc(x.title)}</strong><small>${esc(x.source)} · ${esc(x.why)} · avant ${shortDate(x.due)}</small></span>${btn(owner(d)?'Voir':'Attribuer','deal',owner(d)?'btn-quiet':'btn-primary',`data-id="${d.id}"`)}</div>`}).join('')||'<p class="body-copy">Aucune demande à répartir dans ce périmètre.</p>'}</div></section>`}
function teamOverview(rows){
  const t=total(rows),deals=visibleDeals(rows),risk=deals.filter(d=>age(d)>=11||!owner(d));
  const atlas=state.role==='direction'?renderTerritoryCompass({cities:CITIES,units:BUS,deals:DEALS,invoices:INVOICES(),selectedCity:state.mapCity,owner,age,money}):'';
  const portfolios=renderTeamPortfolios({rows,members:MEMBERS,deals,owner,age,next,avatar,money,maxVisible:4});
  const handoffs=renderHandoffFlow({deals,dispatch:Data.DISPATCH,owner,age,next,member,money});
  return `<div class="team-hero glass"><div><div class="eyebrow">ÉQUIPE · ${scopeName(rows)}</div><h2>${risk.length} affaires à reprendre avec l’équipe.</h2><p>${MEMBERS.filter(m=>rows.some(b=>b.id===m.bu)).length} commerciaux · ${t.uncovered} besoins sans profil.</p></div><div class="team-hero-stat"><strong>${money(t.signed)}</strong><span>signés / ${money(t.target)} visés en novembre</span></div></div>${atlas}${portfolios}${handoffs}<details class="team-data-more"><summary>Voir les résultats par BU et tous les responsables</summary><div class="content-grid"><section class="glass card">${section('Résultat par BU','Montants signés face aux objectifs · novembre')}${progressByBu(rows)}</section><section class="glass card">${section('Responsables','Rendez-vous et affaires à reprendre')}${memberRows(rows)}</section></div></details>`;
}
function stageBars(rows){let ids=new Set(rows.map(b=>b.id)),d=state.role==='sales'?visibleDeals(rows):DEALS.filter(x=>ids.has(x.bu)),items=STAGES.map(s=>({name:s,value:sum(d.filter(x=>x.stage===s),'amount'),count:d.filter(x=>x.stage===s).length})),max=Math.max(...items.map(x=>x.value),1);return `<div class="pipe-bars">${items.map(x=>`<button class="bar-row" data-action="pipe-stage" data-value="${x.name}"><span>${x.name}<small>${x.count} affaire${x.count>1?'s':''}</small></span><div class="bar-track"><span class="bar-fill" style="width:${x.value/max*100}%"></span></div><strong>${money(x.value)}</strong></button>`).join('')}</div><p class="panel-footnote">Pipe ouvert, non pondéré · novembre · ${state.role==='sales'?'affaires accessibles à Nora':'périmètre de BU'} · cliquer pour consulter les affaires de l’étape.</p>`}
function dealsTable(rows,limit=15,stage=''){
  const deals=visibleDeals(rows).filter(d=>!stage||d.stage===stage).sort((a,b)=>(!owner(a)?-1:1)-(!owner(b)?-1:1)||age(b)-age(a));
  const first=Math.min(6,limit),head='<thead><tr><th>Compte / besoin</th><th>Étape</th><th>Pipe</th><th>Responsable</th><th>Dernier échange</th><th>Prochaine action</th></tr></thead>';
  const row=d=>`<tr data-action="deal" data-id="${d.id}" tabindex="0"><td><strong>${esc(d.account)}</strong><small>${esc(d.need)} · ${esc(bu(d.bu).name)}</small></td><td>${esc(d.stage)}</td><td class="money">${money(d.amount)}</td><td>${owner(d)?esc(member(owner(d))?.name):'<span class="risk">À attribuer</span>'}</td><td class="${age(d)>=11?'risk':''}">${age(d)} j</td><td><button class="text-button" data-action="deal" data-id="${d.id}">${esc(next(d))} ${icon('arrow')}</button></td></tr>`;
  const table=items=>`<div class="table-wrap"><table class="data-table">${head}<tbody>${items.length?items.map(row).join(''):'<tr><td colspan="6">Aucune affaire dans ce filtre.</td></tr>'}</tbody></table></div>`;
  return `${table(deals.slice(0,first))}${deals.length>first?`<details class="progressive-list deals-more"><summary>Voir les ${deals.length-first} autres dossiers →</summary>${table(deals.slice(first))}</details>`:''}`;
}
function teamObjectives(rows){let t=total(rows);return `<div class="content-grid"><section class="glass card">${section('Objectifs de novembre','Le réalisé et l’écart par BU')}${progressByBu(rows)}</section><section class="glass card">${section('Activité par étape','Rendez-vous, besoins, profils, entretiens et missions signées')}${conversionGraphic(t.funnel,['RDV déclarés','Besoins qualifiés','Profils présentés','Entretiens','Missions signées'])}</section></div><section class="glass card table-card">${section('Revue des affaires','Responsable, dernière interaction et action suivante')}${dealsTable(rows,14)}</section>${dispatchCard(rows)}`}
function teamLoadCompare(rows){
  const deals=visibleDeals(rows),members=MEMBERS.filter(m=>rows.some(b=>b.id===m.bu));
  const counts=members.map(m=>{const owned=deals.filter(d=>owner(d)===m.id),late=owned.filter(d=>age(d)>=11).length;return {member:m,current:owned.length-late,late}});
  const max=Math.max(1,...counts.map(x=>x.current+x.late));
  return `<div class="team-load-legend"><span><i class="current"></i>À suivre</span><span><i class="late"></i>À reprendre · 11 j sans échange</span></div><div class="team-load">${counts.map(({member:m,current,late})=>`<button type="button" class="team-load-row" data-action="member" data-id="${m.id}" aria-label="${esc(m.name)} : ${current} affaires à suivre, ${late} à reprendre"><span class="person">${avatar(m.id)}<span><strong>${esc(m.name)}</strong><small>${esc(bu(m.bu).name)}</small></span></span><span class="team-load-track" aria-hidden="true"><i class="current" style="width:${current/max*100}%"></i><i class="late" style="width:${late/max*100}%"></i></span><span class="team-load-numbers"><b>${current}</b><small>à suivre</small><b>${late}</b><small>à reprendre</small></span>${icon('arrow')}</button>`).join('')}</div>`;
}
function teamPlans(rows){let d=visibleDeals(rows).sort((a,b)=>dueISO(a).localeCompare(dueISO(b))||age(b)-age(a));return `<div class="content-grid"><section class="glass card">${section('Prochaines actions datées','Une action avec un dossier et une échéance')}${d.slice(0,8).map((x,i)=>`<button class="task-item" data-action="deal" data-id="${x.id}"><span class="task-index">${shortDate(dueISO(x))}</span><span class="task-main"><strong>${esc(next(x))} · ${esc(x.account)}</strong><small>${owner(x)?esc(member(owner(x))?.name):'Responsable à nommer'} · ${esc(bu(x.bu).name)}</small></span>${icon('arrow')}</button>`).join('')}</section><section class="glass card">${section('Charge par responsable','Affaires ouvertes attribuées · détails par commercial')}${teamLoadCompare(rows)}</section></div>${dispatchCard(rows)}`}
function teamResearch(rows){
  const cases=[['gc','Véridian','Projet de transformation finance','Un échange a mentionné un chantier 2027. Valider le sponsor, le calendrier et le budget.','Compte rendu de rendez-vous'],['data','Néoma','Renfort plateforme Data','Affinité observée avec l’équipe Data. Aucun besoin client actif confirmé.','Historique de compte'],['ouest','NovaSanté','Modernisation BI','Signal ancien à qualifier avant de l’intégrer au pipe.','Observation historique'],['aero','Airéa','Calendrier des projets Data','Question ouverte à confirmer lors du prochain rendez-vous.','Agenda client'],['ind','Atelieria','Capacité cloud et infrastructure','Un échange technique suggère une piste ; vérifier les travaux réellement ouverts.','Compte rendu technique'],['nord','Noroît','Renfort applicatif potentiel','Affinité historique à qualifier avec le bon responsable.','Historique de compte'],['so','Rivage','Chantier data plateforme','Demande de rendez-vous reçue ; cadrer périmètre et calendrier avant entrée en pipe.','Demande entrante'],['med','Calanques','Programme cybersécurité','Besoin détecté dans une conversation ; obtenir la confirmation du client.','Compte rendu'],['est','Alsance','Maintenance et modernisation SI','Observation historique ; pas de besoin actif confirmé.','Historique de compte']].filter(x=>rows.some(b=>b.id===x[0]));
  return `<section class="glass card research-board">${section('Pistes à vérifier',`${cases.length} ${cases.length>1?'signaux':'signal'} dans le périmètre · la source est indiquée pour chaque piste`)}<div class="research-grid">${cases.map(([id,account,title,copy,source])=>{const linked=visibleDeals(rows).filter(d=>d.account===account&&d.bu===id);return `<article class="research-card"><div class="research-main"><div class="research-account">${accountLogo(account)}<strong>${esc(account)}</strong><small>${esc(bu(id).name)}</small></div><div class="research-copy"><h3>${esc(title)}</h3><p>${esc(copy)}</p></div></div><div class="research-footer"><span>${esc(source)} · à confirmer</span>${linked.length?btn(`${linked.length} affaire${linked.length>1?'s':''} liée${linked.length>1?'s':''}`,'account','btn-quiet',`data-id="${esc(account)}"`):'<span>Aucune affaire ouverte</span>'}</div></article>`}).join('')||'<p class="body-copy">Aucun signal documenté dans ce périmètre.</p>'}</div></section>`;
}
function heatmap(rows){
  const entries=(Data.TOUCHPOINTS||[]).filter(t=>rows.some(b=>b.id===t.bu)&&(state.role!=='sales'||visibleDeals(rows).some(d=>d.account===t.account)));
  const hours=['08','09','10','11','12','13','14','15','16','17'];
  const cells=hours.map(hour=>{const count=entries.filter(t=>t.when.startsWith(hour)).length;
    return count?`<button type="button" class="heatmap-cell level-${Math.min(3,count)} ${state.activityHour===hour?'selected':''}" title="Mercredi ${hour} h · ${count} interaction${count>1?'s':''}" data-action="heatmap-hour" data-value="${hour}" aria-label="Mercredi ${hour} h, ${count} interaction${count>1?'s':''} · filtrer le journal"></button>`:`<span class="heatmap-cell level-0" title="Mercredi ${hour} h · aucune interaction enregistrée"></span>`;
  }).join('');
  return `<div class="heatmap" role="group" aria-label="Interactions du mercredi 25 novembre par heure"><div class="heatmap-label"></div>${hours.map(h=>`<span class="heatmap-hour">${h} h</span>`).join('')}<strong>Mer 25</strong>${cells}</div><p class="panel-footnote">Interactions horodatées le 25 novembre. Le détail horaire des autres journées n’est pas disponible.</p>`;
}
function teamActivity(rows){return `<div class="content-grid"><section class="glass card">${section('Interactions du 25 novembre','Choisissez une heure pour filtrer le journal')}${heatmap(rows)}</section><section class="glass card">${section(state.activityHour?`Journal · ${state.activityHour} h`:'Journal relié aux dossiers','Actions, comptes et responsables',state.activityHour?btn('Toutes les heures','clear-activity-hour','btn-quiet'):'')}${activityStream(rows,state.activityHour)}</section></div>${weekRhythm()}${dispatchCard(rows)}`}
function franceMap(selected){return `<div class="france-canvas" role="group" aria-label="Choisir une ville sur la carte de France">${CITIES.map(c=>{let t=total(scope(c.name)),active=c.name===selected;return `<button class="city-marker ${active?'active':''} ${pct(t.signed,t.target)<60?'behind':''}" style="left:${c.x}%;top:${c.y}%;--marker-size:${Math.max(12,Math.min(22,10+t.signed/25))}px" data-action="map-city" data-value="${c.name}" aria-label="${c.name}, ${money(t.signed)} signés pour ${money(t.target)} d’objectif"><span class="city-dot"></span><span class="city-name">${c.name}</span></button>`}).join('')}</div>`}
function adminPage(){let city=state.mapCity,allBus=scope(city),rows=scope(city,state.mapBu),t=total(rows),cityT=total(allBus),d=DEALS.filter(x=>rows.some(b=>b.id===x.bu)),inv=INVOICES().filter(x=>rows.some(b=>b.id===x.bu)&&x.status==='overdue'&&(state.role!=='sales'||x.owner==='nora'));return `<div class="map-layout"><section class="glass card map-panel">${section('France commerciale','Choisissez une ville puis une business unit')}${franceMap(city)}<div class="map-city-list" aria-label="Villes disponibles">${CITIES.map(c=>`<button type="button" class="${city===c.name?'active':''}" data-action="map-city" data-value="${c.name}"><span>${c.name}</span><small>${money(total(scope(c.name)).signed)} signés · novembre</small></button>`).join('')}</div><div class="map-legend"><span><i></i> Taille : signé de novembre</span><span>Contour : ville sélectionnée</span></div></section><section class="glass card city-panel"><div class="city-overline">TERRITOIRE SÉLECTIONNÉ</div><div class="city-header"><h2>${esc(city)}</h2><strong>${money(cityT.signed)} <small>/ ${money(cityT.target)}</small></strong></div><div class="city-progress"><span style="width:${Math.min(100,pct(cityT.signed,cityT.target))}%"></span></div><p class="city-hint">${percent(cityT.signed,cityT.target)} de l’objectif · ${allBus.length} BU · ${cityT.needs} besoins ouverts</p><div class="city-select-label">CHOISIR UNE BU</div><div class="bu-list"><button class="bu-option ${state.mapBu==='all'?'active':''}" data-action="map-bu" data-value="all"><span><strong>Tout ${esc(city)}</strong><small>Vue consolidée</small></span><b>${money(cityT.signed)}</b></button>${allBus.map(b=>`<button class="bu-option ${state.mapBu===b.id?'active':''}" data-action="map-bu" data-value="${b.id}"><span><strong>${esc(b.name)}</strong><small>${percent(b.signed,b.target)} de l’objectif · ${b.members.length} ${b.members.length>1?'commerciaux':'commercial'}</small><small>${b.uncovered} besoins sans profil · ${b.bench} disponibles</small>${clientStack(b.accounts||[])}</span><b>${money(b.signed)}</b></button>`).join('')}</div><div class="city-insight"><div class="city-select-label">CE QUI DEMANDE UNE SUITE</div><button type="button" data-action="city-focus" data-value="deals"><strong>${d.filter(x=>!owner(x)||age(x)>=11).length}</strong><span>affaires à reprendre</span>${icon('arrow')}</button><button type="button" data-action="city-focus" data-value="finance"><strong>${money(sum(inv,'amount')/1000)}</strong><span>de factures échues</span>${icon('arrow')}</button><button type="button" data-action="city-focus" data-value="team"><span class="city-avatar-stack">${rows.flatMap(b=>b.members).slice(0,3).map(id=>avatar(id)).join('')}</span><span>${rows.flatMap(b=>b.members).length} responsable${rows.flatMap(b=>b.members).length>1?'s':''} à mobiliser</span>${icon('arrow')}</button></div></section></div><div class="detail-heading"><div><div class="eyebrow">PERFORMANCE · ${esc(city).toUpperCase()}</div><h2>${state.mapBu==='all'?'Toutes les BU':esc(bu(state.mapBu).name)}</h2><p>${d.length} affaires, ${t.uncovered} besoins sans profil et ${inv.length} facture${inv.length>1?'s':''} échue${inv.length>1?'s':''} sur ce territoire.</p></div></div><div class="territory-grid"><div class="glass metric-tile"><span>Pipe ouvert</span><strong>${money(t.pipe)}</strong></div><div class="glass metric-tile"><span>Factures en retard</span><strong>${money(sum(inv,'amount')/1000)}</strong></div><div class="glass metric-tile"><span>RDV déclarés</span><strong>${fmt(t.funnel[0])}</strong></div></div><div class="sub-tabs admin-detail-tabs" role="group" aria-label="Détail du territoire">${[['performance','Performance'],['team','Responsables'],['affaires','Affaires'],['finance','Finance']].map(([id,label])=>`<button type="button" data-action="admin-view" data-value="${id}" class="${state.adminView===id?'active':''}" aria-pressed="${state.adminView===id}">${label}</button>`).join('')}</div><div class="admin-detail" id="admin-detail">${state.adminView==='team'?`<section class="glass card">${section('Qui porte les affaires','Activité et charge des responsables')}${memberRows(rows)}</section>${dispatchCard(rows)}`:state.adminView==='affaires'?`<section class="glass card table-card">${section('Affaires à faire avancer','Ville et BU filtrent les dossiers')}${dealsTable(rows,12)}</section>`:state.adminView==='finance'?invoicePanel(rows,8):`<section class="glass card">${section('Activité à chaque étape','Volumes du même mois et du même périmètre')}${conversionGraphic(t.funnel,['RDV','Besoins','Profils','Entretiens','Signatures'],state.mapBu==='all'?`Toutes les BU · ${city}`:`${bu(state.mapBu)?.name} · ${city}`)}</section>`}</div>`}
function teamPage(){let rows=visibleBus();return `${heading('MA JOURNÉE / ÉQUIPE','Équipe commerciale','Du résultat au travail de chaque personne : objectifs, attribution, activité et territoires.')}${teamNav()}${state.teamTab==='administration'?adminPage():`${filters()}${state.teamTab==='vue'?teamOverview(rows):state.teamTab==='objectifs'?teamObjectives(rows):state.teamTab==='plans'?teamPlans(rows):state.teamTab==='recherches'?teamResearch(rows):teamActivity(rows)}`}`}

function territoryHeroScenario(){
  const city=state.mapCity;
  return `<section class="territory-hero glass"><div class="territory-copy"><div class="eyebrow">CARTE DE FRANCE · TERRITOIRES</div><h2>Dans quelle ville intervenir ?</h2><p>Choisissez une ville : le territoire, ses BU, les affaires et les factures restent liés au même périmètre de novembre.</p><button type="button" class="btn btn-primary" data-action="go-map">Ouvrir la carte des agences →</button><p class="panel-footnote">Taille des points : valeur signée · période : novembre 2026 · source : contrats signés. La liste des villes et des BU est aussi disponible dans la vue détaillée.</p></div><div class="territory-map">${franceMap(city)}</div></section>`;
}

function choicePage(){
  return `${heading('BELLUMAI · DÉMARRER','Votre cockpit commence avec votre périmètre.','Choisissez votre parcours. Les chiffres de l’exemple ne seront jamais mêlés aux agences que vous créez.')}
  <div class="territory-hero glass"><div class="territory-copy"><div class="eyebrow">01 / VOTRE ORGANISATION</div><h2>Construire votre espace.</h2><p>Créez une agence, choisissez sa ville, puis ajoutez équipes, business units et personnes. Cet aperçu garde vos choix sur cet appareil. Les KPI attendent des sources réelles.</p><button class="btn btn-primary" data-action="mode-start-personal">Configurer mon espace →</button><div class="org-actions"><button class="text-button" data-action="mode-start-scenario">Explorer un exemple →</button><span>Données séparées de votre espace</span></div></div><div class="territory-map">${organizationMap(state.organization,'all')}</div></div>
  <div class="org-grid"><section class="glass card"><div class="section-title"><div><h2>Ce que vous configurez ici</h2><p>Agence → ville → équipe → personne et BU.</p></div></div><p class="body-copy">L’organigramme et la carte sont modifiables. Aucune personne ne reçoit d’invitation depuis cet espace.</p></section><section class="glass card"><div class="section-title"><div><h2>Ce que montre l’exemple</h2><p>Ma journée, agenda, performance, factures et Laura.</p></div></div><p class="body-copy">Retrouvez un parcours complet, du premier signal à l’encaissement.</p></section></div>`;
}

function personalPage(active){
  const org=state.organization,wf=state.personalWorkflows,p=state.profile;
  const overview=organizationOverview(org,{role:state.role,city:state.orgCity});
  const words=personalHeading(p,active),intro=heading(`MA JOURNÉE${active==='today'?'':` / ${dayNav.find(([id])=>id===active)?.[1].toUpperCase()}`}`,words.title,words.copy);
  const identity=state.profileEditing?onboardingForm(p):identityStrip(p,active,org);
  if(active==='team'){
    const view=state.teamTab;
    const adminNav=view==='administration'&&state.role==='direction'?`<div class="sub-tabs" aria-label="Administration locale"><button type="button" class="${state.adminSub==='map'?'active':''}" data-action="admin-sub" data-value="map">Carte & structure</button><button type="button" class="${state.adminSub==='report'?'active':''}" data-action="admin-sub" data-value="report">Rapport d’activité</button></div>`:'';
    const companyReports=reportsForCompany(state.reports,p.companyName);
    const report=companyReports.find(item=>item.id===state.reportActiveId);
    const reportPage=report?renderActivityReport(report,{channel:state.reportSeries,owner:state.reportOwner,preview:state.reportPreview,companyName:report.companyName||'votre ESN'}):renderActivityReportSetup(org,{period:state.reportPeriod,city:state.orgCity,agency:state.orgAgency,unit:state.orgUnit,reports:companyReports});
    const content=view==='administration'?`${adminNav}${state.role==='direction'&&state.adminSub==='report'?reportPage:organizationHub(org,{role:state.role,city:state.orgCity,agency:state.orgAgency,unit:state.orgUnit,editing:state.orgEditing,declaredLocations:p.companyLocations})}`:renderPersonalSection(`team-${view}`,{workflow:wf,organization:org,profile:p,overview,role:state.role,activitySeries:state.activitySeries,activityDay:state.activityDay});
    return `${intro}${identity}${teamNav()}${content}`;
  }
  if(active==='pilotage'){
    const section=pilotTabs.some(([id])=>id===state.pilotSection)?state.pilotSection:'cockpit';
    const nav=`<div class="anchor-nav" aria-label="Sections de Pilotage">${pilotTabs.map(([id,label])=>`<a href="#pilotage?section=${id}" data-anchor="${id}" class="${section===id?'active':''}">${label}</a>`).join('')}</div>`;
    const map=section==='cockpit'?`<div class="pw-quick-links territory-shortcut"><span>${org.agencies.filter(a=>!a.archivedAt).length} agence${org.agencies.filter(a=>!a.archivedAt).length>1?'s':''} créée${org.agencies.filter(a=>!a.archivedAt).length>1?'s':''} · implantations déclarées à confirmer</span><button type="button" data-action="org-open-map">Carte de France et structure →</button></div>`:'';
    return `${intro}${identity}${nav}<section class="pilot-section" id="p-${section}"><div class="section-kicker">${esc(pilotTabs.find(([id])=>id===section)?.[1].toUpperCase())} · VOTRE ESPACE</div>${renderPersonalSection(`pilot-${section}`,{workflow:wf,organization:org,profile:p,overview,role:state.role})}${section==='finance'?financeLab():''}${map}</section>`;
  }
  if(active==='agenda')return `${intro}${identity}${renderPersonalWorkflows(wf,org,'agenda',{day:state.agendaDay})}`;
  return `${intro}${identity}${renderPersonalWorkflows(wf,org,'today',{series:state.activitySeries,day:state.activityDay})}`;
}

function conversionGraphic(values,labels,chartScope=scopeName()){let base=values[0]||1;return `<div class="funnel-viz">${values.map((v,i)=>`<div class="funnel-viz-row"><div class="funnel-viz-label"><strong>${fmt(v)}</strong><span>${labels[i]}</span></div><div class="funnel-viz-shape" style="width:${Math.max(22,Math.sqrt(v/base)*100)}%"></div><small>${i?'Activité du mois':'Premier volume suivi'}</small></div>`).join('')}</div><p class="panel-footnote">Volumes enregistrés en novembre · ${esc(chartScope)}. Chaque étape compte ses propres actions, sans calcul de conversion.</p><button class="text-button" type="button" data-action="pilot-pipe">Ouvrir les affaires du périmètre →</button>`}
function invoicePanel(rows=visibleBus(),limit=6,showLink=true){let ids=new Set(rows.map(b=>b.id)),list=INVOICES().filter(x=>ids.has(x.bu)&&x.status!=='paid'&&(state.role!=='sales'||x.owner==='nora')).sort((a,b)=>a.due.localeCompare(b.due)).slice(0,limit);return `<section class="glass card invoice-panel">${section('À encaisser','Factures ouvertes, distinctes du CA signé',showLink?`<button class="text-button" data-action="pilot-finance">Voir la finance ${icon('arrow')}</button>`:'')}<div class="ledger-list">${list.map(x=>`<button class="invoice-row" data-action="invoice" data-id="${x.id}"><span><strong>${esc(x.account)}</strong><small>${x.id} · ${esc(bu(x.bu).name)} · ${esc(member(x.owner)?.name)}</small></span><span><b>${money(x.amount/1000)}</b><small class="${x.status==='overdue'?'risk':''}">${x.status==='overdue'?`Échue le ${shortDate(x.due)}`:`Échéance ${shortDate(x.due)}`}</small></span>${icon('arrow')}</button>`).join('')||'<p class="body-copy">Aucune facture ouverte dans ce périmètre.</p>'}</div><p class="panel-footnote">${list.length} facture${list.length>1?'s':''} affichée${list.length>1?'s':''} sur ce périmètre. Les agrégats BU couvrent davantage de factures.</p></section>`}
function localHero(rows){let t=total(rows),gap=Math.max(0,t.target-t.signed),sales=state.role==='sales',cap=Math.min(100,pct(t.signed,t.target));return `<section class="glass hero-dashboard local-hero"><div class="hero-copy"><div class="eyebrow">NOVEMBRE · ${sales?'BU COMPLÈTE · ':''}${esc(scopeName(rows)).toUpperCase()}</div><div class="hero-number"><strong>${money(t.signed)}</strong><span>/ ${money(t.target)}</span></div><h2>${money(gap)} restent à signer ${sales?'pour la BU':'sur ce périmètre'}.</h2><p>Les contrats signés atteignent ${percent(t.signed,t.target)} de l’objectif. Le pipe ouvert de ${money(t.pipe)} est suivi séparément : il ne garantit pas cet écart.${sales?' Ces montants couvrent toute la BU, y compris les collègues. La liste qui suit ne montre que les affaires accessibles à Nora.':''}</p><button class="text-button" data-action="pilot-pipe">${sales?'Voir mes affaires accessibles':'Examiner les affaires ouvertes'} ${icon('arrow')}</button></div><div class="local-hero-visual"><div class="eyebrow">RÉALISATION DE L’OBJECTIF</div><div class="local-cap-content"><div class="local-cap-figure" role="img" aria-label="${percent(t.signed,t.target)} de l’objectif mensuel atteint"><svg viewBox="0 0 120 120" aria-hidden="true"><defs><linearGradient id="cap-lavender" x1="0" x2="1" y1="0" y2="1"><stop offset="0" stop-color="#b99dff"/><stop offset="1" stop-color="#7657ad"/></linearGradient></defs><circle class="local-cap-track" cx="60" cy="60" r="49" pathLength="100"/><circle class="local-cap-arc" cx="60" cy="60" r="49" pathLength="100" stroke-dasharray="${cap} 100"/></svg><span class="local-cap-label"><strong>${percent(t.signed,t.target)}</strong><small>du cap</small></span></div><div class="local-cap-values"><span>Signé ce mois</span><strong>${money(t.signed)}</strong><span>Cible du mois</span><strong>${money(t.target)}</strong></div></div><div class="local-hero-bottom"><span>Contrats signés · 25 nov.</span><span>${money(gap)} d’écart</span></div></div></section>`}
function localFocus(rows){let d=visibleDeals(rows).filter(x=>!owner(x)||age(x)>=11).sort((a,b)=>age(b)-age(a));return `<section class="glass card">${section('Les affaires qui expliquent le risque','Ouvrir le dossier pour affecter une suite datée')}${d.slice(0,5).map(x=>`<button class="brief-item" data-action="deal" data-id="${x.id}"><span><strong>${esc(x.account)} · ${esc(next(x))}</strong><small>${owner(x)?`${age(x)} j sans échange · ${esc(member(owner(x))?.name)}`:'Sans responsable'} · ${money(x.amount)}</small></span>${icon('arrow')}</button>`).join('')||'<p class="body-copy">Aucune affaire en retard dans ce périmètre.</p>'}</section>`}
function singlePilotSection(html){
  const selected=pilotTabs.some(([id])=>id===state.pilotSection)?state.pilotSection:'cockpit';
  for(const [id] of pilotTabs){
    if(id===selected)continue;
    const start=html.indexOf(`<section class="pilot-section" id="p-${id}">`);
    if(start<0)continue;
    const tags=/<\/?section\b[^>]*>/g;tags.lastIndex=start;let depth=0,end=start;
    for(let match;(match=tags.exec(html));){depth+=match[0].startsWith('</')?-1:1;if(depth===0){end=tags.lastIndex;break}}
    if(end>start)html=html.slice(0,start)+html.slice(end);
  }
  return html;
}
function decisionWatch(rows){let cases=visibleDeals(rows).filter(d=>owner(d)).sort((a,b)=>dueISO(a).localeCompare(dueISO(b))||age(b)-age(a)).slice(0,4);return cases.map(d=>`<button class="brief-item" data-action="deal" data-id="${d.id}"><span><strong>${accountLogo(d.account)}${esc(d.account)} · ${esc(d.stage)}</strong><small>${esc(next(d))} · avant le ${shortDate(dueISO(d))} · ${esc(member(owner(d))?.name||'Responsable à nommer')}</small></span><b>${money(d.amount)}</b></button>`).join('')||'<p class="body-copy">Aucune décision datée sur ce périmètre.</p>'}
function pilotage(){let rows=visibleBus(),t=total(rows),g=GOAL(),globalScope=state.role==='direction'&&state.city==='all'&&state.bu==='all',outstanding=INVOICES().filter(x=>rows.some(b=>b.id===x.bu)&&x.status==='overdue'&&(state.role!=='sales'||x.owner==='nora')),paid=INVOICES().filter(x=>rows.some(b=>b.id===x.bu)&&x.status==='paid'&&(state.role!=='sales'||x.owner==='nora'));return singlePilotSection(`${heading('MA JOURNÉE / PILOTAGE','Performance commerciale',`${scopeName(rows)} · ${money(t.signed)} signés en novembre · ${t.uncovered} besoins sans profil · ${outstanding.length} facture${outstanding.length>1?'s':''} suivie${outstanding.length>1?'s':''} échue${outstanding.length>1?'s':''}.`)}${filters()}${state.role==='direction'?`<button type="button" class="text-button territory-shortcut" data-action="go-map">Carte de France · choisir une ville et une BU →</button>`:''}<div class="anchor-nav" aria-label="Sections de Pilotage">${pilotTabs.map(([id,label])=>`<a href="#pilotage?section=${id}" data-anchor="${id}" class="${state.pilotSection===id?'active':''}">${label}</a>`).join('')}</div><section class="pilot-section" id="p-cockpit"><div class="section-kicker">VUE D’ENSEMBLE · NOVEMBRE 2026</div>${localHero(rows)}<div class="territory-grid"><button type="button" class="glass metric-tile metric-link" data-action="pilot-pipe" aria-label="Voir les affaires du pipe ouvert"><span>Pipe ouvert · ${state.role==='sales'?'BU complète':'périmètre'}</span><strong>${money(t.pipe)}</strong><small>Valeur des affaires ouvertes · novembre</small></button><button type="button" class="glass metric-tile metric-link" data-action="pilot-staffing" aria-label="Voir la couverture des besoins sans profil"><span>Besoins sans profil · ${state.role==='sales'?'BU complète':'périmètre'}</span><strong>${t.uncovered}</strong><small>sur ${t.needs} besoins</small></button><button type="button" class="glass metric-tile metric-link" data-action="pilot-finance" aria-label="Voir les factures échues"><span>Factures échues</span><strong>${money(sum(outstanding,'amount')/1000)}</strong><small>Parmi les factures suivies</small></button></div><div class="content-grid">${globalScope?reverseLadder():localFocus(rows)}<section class="glass card">${section('Activité par étape','Rendez-vous, besoins, profils, entretiens et signatures')}${conversionGraphic(t.funnel,['RDV déclarés','Besoins','Profils présentés','Entretiens','Missions signées'])}</section></div>${globalScope?`<section class="glass card">${section('Trajectoire des démarrages','Réalisé cumulé et cap annuel')}${annualChart()}</section>${weekRhythm()}`:''}</section><section class="pilot-section" id="p-pipe"><div class="section-kicker">PIPE · VALEUR ET PROCHAINE ÉTAPE</div>${section('Chaque affaire a une suite',`Montants ouverts et propriétaires · ${scopeName(rows)}`)}<div class="content-grid"><section class="glass card">${stageBars(rows)}</section><section class="glass card">${section('Décisions attendues','Prochaine étape et date par affaire')}${decisionWatch(rows)}</section></div><section class="glass card table-card">${section(state.pipeStage?`Affaires · ${state.pipeStage}`:'Dossiers à traiter','Dernier échange, responsable, valeur et action suivante',state.pipeStage?btn('Effacer le filtre','clear-pipe-stage','btn-quiet'):'')}${dealsTable(rows,20,state.pipeStage)}</section></section><section class="pilot-section" id="p-staffing"><div class="section-kicker">STAFFING · COUVERTURE DES BESOINS</div>${section('Besoins à couvrir',`${t.uncovered} sur ${t.needs} besoins ouverts · ${t.bench} consultants disponibles`)}<div class="territory-grid"><div class="glass metric-tile"><span>Besoins ouverts · ${state.role==='sales'?'BU complète':'périmètre'}</span><strong>${t.needs}</strong></div><div class="glass metric-tile"><span>Sans profil · ${state.role==='sales'?'BU complète':'périmètre'}</span><strong>${t.uncovered}</strong><small>${percent(t.uncovered,t.needs)} des besoins</small></div><div class="glass metric-tile"><span>Consultants disponibles · ${state.role==='sales'?'BU complète':'périmètre'}</span><strong>${t.bench}</strong></div></div><section class="glass card staffing-board">${renderStaffingInsights({rows,deals:visibleDeals(rows),owner,age,next,money,shortDate,dueISO})}</section></section><section class="pilot-section" id="p-finance"><div class="section-kicker">FINANCE · SIGNÉ, FACTURÉ, ENCAISSÉ</div>${section('Contrats, factures et règlements','Suivez les montants signés, facturés et encaissés sur ce périmètre.')}<div class="territory-grid"><div class="glass metric-tile"><span>Signé · novembre</span><strong>${money(t.signed)}</strong><small>Valeur contractuelle</small></div><div class="glass metric-tile"><span>Facturé · novembre · ${state.role==='sales'?'BU complète':'périmètre'}</span><strong>${money(sum(rows,'invoiced'))}</strong><small>Agrégat des BU</small></div><div class="glass metric-tile"><span>Encaissé · factures suivies</span><strong>${money(sum(paid,'amount')/1000)}</strong><small>${paid.length} facture${paid.length>1?'s':''} encaissée${paid.length>1?'s':''} dans ce suivi</small></div><div class="glass metric-tile"><span>Échu · périmètre</span><strong>${money(sum(outstanding,'amount')/1000)}</strong><small>${outstanding.length} pièce${outstanding.length>1?'s':''} en retard</small></div></div>${invoicePanel(rows,8,false)}${financeLab()}<section class="glass card table-card">${section('Finance par BU','Signé, facturé et factures en retard par business unit') }<div class="table-wrap"><table class="data-table"><thead><tr><th>Business unit</th><th>Signé</th><th>Facturé</th><th>Factures échues suivies</th><th></th></tr></thead><tbody>${rows.map(b=>`<tr><td><strong>${esc(b.name)}</strong><small>${esc(b.city)}</small></td><td>${money(b.signed)}</td><td>${money(b.invoiced)}</td><td>${money(sum(INVOICES().filter(x=>x.bu===b.id&&x.status==='overdue'),'amount')/1000)}</td><td><button class="text-button" data-action="bu" data-id="${b.id}">Voir la BU ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div></section></section><div class="note">${icon('info')}<span>Signé, pipe, facturé et encaissé sont quatre mesures distinctes. Le registre de six factures couvre moins de pièces que les agrégats facturés des BU.</span></div>`)}

function dealDrawer(d){if(!d)return '';let b=bu(d.bu),who=owner(d),related=INVOICES().filter(x=>x.account===d.account);return `<div class="drawer-header"><div><div class="eyebrow">AFFAIRE · ${esc(b.city)} / ${esc(b.name)}</div><h2>${accountLogo(d.account)}${esc(d.account)}</h2><p>${esc(d.need)} · ${esc(d.stage)}</p></div><button class="icon-button" data-action="close" aria-label="Fermer">${icon('close')}</button></div><div class="drawer-body"><div class="drawer-amount">${money(d.amount)}<span>Pipe ouvert non pondéré</span></div><div class="drawer-facts"><div><span>Responsable</span><strong>${who?esc(member(who)?.name):'<em class="risk">À attribuer</em>'}</strong></div><div><span>Dernier échange</span><strong>${age(d)?`Il y a ${age(d)} jours au 25 nov. 2026`:'25 nov. 2026'}</strong></div><div><span>Prochaine action</span><strong>${esc(next(d))} · ${shortDate(dueISO(d))}</strong></div><div><span>Source</span><strong>Dossier commercial</strong></div></div>${state.role!=='sales'?`<div class="drawer-separator"></div><h3>Répartir l’affaire</h3><p class="body-copy">Le changement de responsable se reflète dans la charge et les demandes à distribuer.</p><label class="drawer-field">Responsable<select class="select" data-change="assign-deal" data-id="${d.id}"><option value="">À attribuer</option>${b.members.map(id=>`<option value="${id}" ${who===id?'selected':''}>${esc(member(id)?.name)}</option>`).join('')}</select></label>`:''}<div class="drawer-separator"></div><h3>Résultat et prochaine suite</h3><label class="drawer-field">Issue de l’échange<select class="select" data-outcome-id="${d.id}"><option value="">Choisir un résultat</option>${[['rdv','Rendez-vous planifié'],['besoin','Besoin confirmé'],['reponse','Réponse reçue'],['sans_reponse','Sans réponse']].map(([key,label])=>`<option value="${key}" ${state.outcomes[d.id]?.type===key?'selected':''}>${label}</option>`).join('')}</select></label><label class="drawer-field">À faire avant le<input class="select" type="date" data-outcome-due="${d.id}" min="${todayISO()}" value="${editableDue(dueISO(d))}" required></label><label class="drawer-field">Note interne<textarea data-outcome-note="${d.id}" rows="3" placeholder="Contexte et prochaine étape pour l’équipe">${esc(state.outcomes[d.id]?.note||'')}</textarea></label>${btn('Consigner la suite','save-outcome','btn-primary',`data-id="${d.id}"`)}${state.outcomes[d.id]?`<div class="outcome-saved">Suite consignée · ${esc(next(d))} avant ${shortDate(dueISO(d))}</div>`:''}${related.length?`<div class="drawer-separator"></div><h3>Facturation liée</h3>${related.map(x=>`<button class="drawer-deal" data-action="invoice" data-id="${x.id}"><strong>${x.id} · ${money(x.amount/1000)}</strong><span>${x.status==='paid'?'Encaissée':x.status==='overdue'?`Échue le ${shortDate(x.due)}`:'À échoir'} · ${esc(x.step)}</span></button>`).join('')}`:''}${(state.transmissions||[]).filter(x=>x.dealId===d.id).map(x=>`<div class="transfer-note"><strong>Transmis à ${esc(member(x.to)?.name)} · avant ${shortDate(x.due)}</strong><p>${esc(x.note)}</p></div>`).join('')}</div>`}
function invoiceDrawer(x){if(!x)return '';let d=DEALS.find(d=>d.account===x.account),note=state.invoiceNotes[x.id];return `<div class="drawer-header"><div><div class="eyebrow">FACTURE · ${esc(x.id)}</div><h2>${accountLogo(x.account)}${esc(x.account)}</h2><p>${esc(bu(x.bu).name)} · ${esc(member(x.owner)?.name)}</p></div><button class="icon-button" data-action="close" aria-label="Fermer">${icon('close')}</button></div><div class="drawer-body"><div class="drawer-amount">${money(x.amount/1000)}<span>${x.status==='paid'?'Encaissée':x.status==='overdue'?`Échue le ${shortDate(x.due)} · statut au 25 nov.`:`À échoir le ${shortDate(x.due)}`}</span></div><div class="drawer-facts"><div><span>Émise le</span><strong>${shortDate(x.issued)}</strong></div><div><span>Échéance</span><strong>${shortDate(x.due)}</strong></div><div><span>Dernière action</span><strong>${esc(x.lastAction)}</strong></div><div><span>Prochaine action</span><strong>${esc(x.step)}</strong></div></div>${d?btn('Ouvrir l’affaire liée','deal','btn-quiet',`data-id="${d.id}"`):''}${x.status!=='paid'?`<div class="drawer-separator"></div><h3>Préparer la relance</h3><p class="body-copy">Consignez une prochaine date et une note. Aucun message n’est envoyé depuis cet espace.</p><label class="drawer-field">Relancer avant le<input type="date" class="select" data-invoice-due="${x.id}" min="${todayISO()}" value="${editableDue(note?.due)}"></label><label class="drawer-field">Note de suivi<textarea data-invoice-note="${x.id}" rows="3" placeholder="Interlocuteur et accord sur la date">${esc(note?.note||'')}</textarea></label>${btn('Consigner la relance','save-invoice','btn-primary',`data-id="${x.id}"`)}${note?`<div class="outcome-saved">Relance planifiée avant ${shortDate(note.due)} · ${esc(note.note)}</div>`:''}`:''}</div>`}
function memberDrawer(id){let m=member(id);if(!m)return '';let d=DEALS.filter(x=>owner(x)===id),w=Data.MEMBER_WEEK?.[id]||{};return `<div class="drawer-header"><div><div class="eyebrow">COMMERCIAL · ${esc(bu(m.bu).city)}</div><h2 class="person">${avatar(id)} ${esc(m.name)}</h2><p>${esc(m.role)} · ${esc(bu(m.bu).name)}</p></div><button class="icon-button" data-action="close" aria-label="Fermer">${icon('close')}</button></div><div class="drawer-body"><div class="drawer-amount">${money(m.signed)}<span>Signés en novembre</span></div><div class="drawer-facts"><div><span>Affaires</span><strong>${d.length}</strong></div><div><span>RDV déclarés · semaine</span><strong>${w.meetings||0}</strong></div><div><span>À relancer</span><strong>${d.filter(x=>age(x)>=11).length}</strong></div></div><div class="drawer-separator"></div><h3>Portefeuille</h3>${d.map(x=>`<button class="drawer-deal" data-action="deal" data-id="${x.id}"><strong>${esc(x.account)} · ${money(x.amount)}</strong><span>${esc(next(x))} · ${shortDate(dueISO(x))}</span></button>`).join('')||'<p>Aucune affaire attribuée.</p>'}${(state.transmissions||[]).filter(x=>x.to===id).map(x=>`<div class="transfer-note"><strong>Passation reçue · ${shortDate(x.due)}</strong><p>${esc(x.note)}</p></div>`).join('')}</div>`}
function buDrawer(id){let b=bu(id);if(!b)return '';return `<div class="drawer-header"><div><div class="eyebrow">BUSINESS UNIT · ${esc(b.city)}</div><h2>${esc(b.name)}</h2><p>Performance et charge du même périmètre</p></div><button class="icon-button" data-action="close" aria-label="Fermer">${icon('close')}</button></div><div class="drawer-body"><div class="drawer-amount">${money(b.signed)}<span>Signés / ${money(b.target)} visés · ${percent(b.signed,b.target)}</span></div><div class="drawer-facts"><div><span>Pipe ouvert</span><strong>${money(b.pipe)}</strong></div><div><span>RDV déclarés</span><strong>${b.funnel[0]}</strong></div><div><span>Besoins sans profil</span><strong>${b.uncovered}</strong></div><div><span>Factures échues</span><strong>${money(sum(INVOICES().filter(x=>x.bu===id&&x.status==='overdue'),'amount')/1000)}</strong></div></div><div class="drawer-separator"></div><h3>Responsables</h3>${b.members.map(mid=>`<button class="drawer-deal" data-action="member" data-id="${mid}"><strong>${esc(member(mid)?.name)}</strong><span>${esc(member(mid)?.role)} · ${money(member(mid)?.signed)}</span></button>`).join('')}<div class="drawer-separator"></div><h3>Affaires et prochaines actions</h3>${renderBuLinkedDeals({b,deals:visibleDeals([b]),owner,age,next,money,shortDate,dueISO,member})}${state.role==='direction'?btn('Voir ce territoire','view-bu','btn-primary',`data-id="${id}"`):''}</div>`}
function eventDrawer(id){let x=(Data.EVENTS||[]).find(e=>e.id===id);if(!x)return '';let d=DEALS.find(d=>d.account===x.account);return `<div class="drawer-header"><div><div class="eyebrow">AGENDA · ${shortDate(x.date)} · ${x.start}</div><h2>${esc(x.title)}</h2><p>${esc(x.kind)} · ${esc(x.place)} · ${esc(member(x.owner)?.name)}</p></div><button class="icon-button" data-action="close" aria-label="Fermer">${icon('close')}</button></div><div class="drawer-body"><div class="drawer-facts"><div><span>Créneau</span><strong>${x.start}–${x.end}</strong></div><div><span>Compte</span><strong>${esc(x.account||'Interne')}</strong></div><div><span>À clarifier</span><strong>${esc(x.next)}</strong></div></div>${d?`<div class="drawer-separator"></div><h3>${x.status==='done'||x.date<todayISO()?'Suite du rendez-vous':'Préparer le rendez-vous'}</h3><p class="body-copy">Besoin, responsable et prochaine étape sur le même dossier.</p>${btn(x.status==='done'||x.date<todayISO()?'Consigner ou vérifier la suite':'Ouvrir le dossier client','deal','btn-primary',`data-id="${d.id}"`)}`:''}</div>`}
function accountDrawer(name){let d=DEALS.filter(x=>x.account===name&&(state.role!=='sales'||visibleDeals().some(v=>v.id===x.id)));return `<div class="drawer-header"><div><div class="eyebrow">COMPTE LIÉ</div><h2>${accountLogo(name)}${esc(name)}</h2><p>Affaires et prochaines étapes liées à ce compte</p></div><button class="icon-button" data-action="close" aria-label="Fermer">${icon('close')}</button></div><div class="drawer-body"><h3>Affaires ouvertes</h3>${d.map(x=>`<button class="drawer-deal" data-action="deal" data-id="${x.id}"><strong>${esc(x.need)} · ${money(x.amount)}</strong><span>${esc(next(x))} · ${shortDate(dueISO(x))}</span></button>`).join('')||'<p>Aucune affaire ouverte sur ce compte.</p>'}</div>`}
function drawerHtml(){if(!drawer)return '';let content=drawer.type==='deal'?dealDrawer(DEALS.find(d=>d.id===drawer.id)):drawer.type==='invoice'?invoiceDrawer(INVOICES().find(x=>x.id===drawer.id)):drawer.type==='member'?memberDrawer(drawer.id):drawer.type==='bu'?buDrawer(drawer.id):drawer.type==='event'?eventDrawer(drawer.id):accountDrawer(drawer.id);return `<div class="drawer-overlay" data-action="close"><aside class="drawer glass" data-drawer-id="${drawer.id}" role="dialog" aria-modal="true" aria-label="Détail commercial" data-dialog="true">${content}</aside></div>`}
function openDrawer(type,id){if(!id)return;closeToken++;drawer={type,id};render(true);$('.drawer .icon-button')?.focus()}
function closeDrawer(){let el=$('.drawer-overlay');if(!el){drawer=null;render(true);return}let token=++closeToken;el.classList.add('closing');setTimeout(()=>{if(token===closeToken){drawer=null;render(true)}},190)}
function render(keepScroll=true){let scroll=$('#page-scroll')?.scrollTop||0,previous=$('.drawer')?.dataset.drawerId,active=applyRoute();const requestedTheme=new URLSearchParams(location.search).get('theme');document.documentElement.dataset.theme=requestedTheme==='dark'?'dark':requestedTheme==='white'?'light':document.querySelector('meta[name="bellum-default-theme"]')?.content==='dark'?'dark':'light';let body=state.mode==='choose'?choicePage():state.mode==='personal'?personalPage(active):active==='today'?todayPage():active==='agenda'?agendaPage():active==='team'?teamPage():pilotage();$('#app').innerHTML=shell(active,body);syncFinanceSalaryMode($('#app [data-finance-form]'));if(state.mode==='scenario'&&active==='pilotage'){const nav=$('.anchor-nav'),selected=document.getElementById('p-'+state.pilotSection);if(nav&&selected)nav.after(selected)}$('#overlay-root').innerHTML=state.mode==='scenario'?drawerHtml():'';if(drawer&&previous===drawer.id)$('.drawer')?.classList.add('no-enter');document.body.classList.toggle('dialog-open',state.mode==='scenario'&&!!drawer);if($('#page-scroll'))$('#page-scroll').scrollTop=keepScroll?scroll:0;if(focusLocalItem){const target=focusLocalItem;focusLocalItem=null;requestAnimationFrame(()=>{const node=document.getElementById(target);for(let parent=node?.parentElement;parent;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;node?.scrollIntoView({block:'center',behavior:'smooth'})})}save();if(state.mode==='scenario'||state.mode==='personal')laura.render();else $('#laura-root').innerHTML=''}
function setMapCity(city){state.adminView='performance';state.mapCity=city;state.mapBu='all';state.city=city;state.bu='all';state.pipeStage='';laura.reset();history.replaceState(null,'',`#team?tab=administration&city=${encodeURIComponent(city)}`);render(false)}
function setMapBu(id){state.adminView='performance';state.mapBu=id;state.bu=id;state.pipeStage='';laura.reset();history.replaceState(null,'',`#team?tab=administration&city=${encodeURIComponent(state.mapCity)}${id==='all'?'':`&bu=${id}`}`);render(false)}
function switchMode(mode){
  state.mode=mode;
  if(mode==='scenario')state.role='direction';
  if(mode==='personal')state.role=state.profile.jobRole||'sales';
  state.teamTab='vue';
  drawer=null;laura.reset();
  navigate('today');
}
function handleClick(e){let el=e.target.closest('[data-route],[data-anchor],[data-action]');if(!el)return;if(el.classList.contains('drawer-overlay')&&e.target.closest('[data-dialog]'))return;
  if(el.dataset.route){navigate(el.dataset.route);return}
  if(el.dataset.anchor){e.preventDefault();state.pilotSection=el.dataset.anchor;if(state.pilotSection==='pipe')state.pipeStage='';history.replaceState(null,'',`#pilotage?section=${state.pilotSection}`);render(false);return}
  let action=el.dataset.action,id=el.dataset.id,val=el.dataset.value;
  if(action==='ask-laura'){document.querySelector('#laura-root [data-laura="toggle"]')?.click();return}
  if(action==='finance-select'){if(state.role!=='direction'||!normalizeFinanceRecords(state.financeRecords).some(record=>record.id===id&&record.workspaceKey===financeWorkspaceKey()))return;state.financeSelectedId=id;render(true);return}
  if(action==='finance-new'){if(state.role!=='direction')return;state.financeSelectedId='new';render(true);requestAnimationFrame(()=>$('#page-scroll [data-finance-form] select[name="personId"]')?.focus());return}
  if(action==='finance-remove'){
    if(state.role!=='direction'||(state.financeSelectedId&&state.financeSelectedId!==id)||!normalizeFinanceRecords(state.financeRecords).some(record=>record.id===id&&record.personId===el.dataset.personId&&record.workspaceKey===financeWorkspaceKey()))return;
    const result=removeFinanceRecord(state.financeRecords,id,financeOptions());
    if(result.error){toast(result.error);return}
    state.financeRecords=result.records;state.financeSelectedId='new';render(true);toast(result.message);return;
  }
  if(action==='activity-series'){if(state.mode!=='personal')return;state.activitySeries=['all','email','linkedin'].includes(val)?val:'all';render(true);return}
  if(action==='annual-series'){if(state.mode!=='scenario')return;state.annualSeries=['all','actual','target'].includes(val)?val:'all';render(true);return}
  if(action==='scenario-series'){if(state.mode!=='scenario')return;state.scenarioSeries=['all','email','linkedin'].includes(val)?val:'all';render(true);return}
  if(action==='scenario-day'){if(state.mode!=='scenario')return;state.scenarioDay=Math.max(0,Math.min(4,Number(val)||0));render(true);return}
  if(action==='activity-day'){if(state.mode!=='personal')return;state.activityDay=val||'';render(true);return}
  if(action==='admin-sub'){if(state.mode!=='personal'||state.role!=='direction')return;state.adminSub=val==='report'?'report':'map';render(false);return}
  if(action==='open-report'){if(state.mode!=='personal'||state.role!=='direction')return;state.teamTab='administration';state.adminSub='report';state.reportActiveId=null;navigate('team','tab=administration');return}
  if(action==='report-series'){if(state.mode!=='personal'||state.role!=='direction')return;state.reportSeries=val;render(true);return}
  if(action==='report-owner'){if(state.mode!=='personal'||state.role!=='direction')return;state.reportOwner=val;render(true);return}
  if(action==='report-preview'){if(state.mode!=='personal'||state.role!=='direction')return;state.reportPreview=!state.reportPreview;render(true);return}
  if(action==='report-new'){if(state.mode!=='personal'||state.role!=='direction')return;state.reportActiveId=null;state.reportPreview=false;render(false);return}
  if(action==='report-select'){if(state.mode!=='personal'||state.role!=='direction'||!reportsForCompany(state.reports,state.profile.companyName).some(r=>r.id===id))return;state.reportActiveId=id;state.reportPreview=false;render(false);return}
  if(action==='report-generate'){
    if(state.mode!=='personal'||state.role!=='direction')return;
    const report=buildActivityReport(state.personalWorkflows,state.organization,state.reportPeriod,{city:state.orgCity,agency:state.orgAgency,unit:state.orgUnit,role:state.role,companyName:state.profile.companyName||'votre ESN'});
    state.reports=[...state.reports,report].slice(-20);state.reportActiveId=report.id;state.reportPreview=false;render(false);toast('Rapport généré et conservé localement. Aucun e-mail envoyé.');return;
  }
  if(action==='report-source'){
    if(state.mode!=='personal'||state.role!=='direction')return;
    if(el.dataset.kind==='email'||el.dataset.kind==='linkedin'){focusLocalItem=`local-activity-${id}`;state.teamTab='activite';navigate('team','tab=activite')}
    else if(el.dataset.kind==='meeting'){focusLocalItem=`local-meeting-${id}`;state.agendaDay='';navigate('agenda')}
    else{focusLocalItem=`local-action-${id}`;state.teamTab='plans';navigate('team','tab=plans')}
    return;
  }
  if(['report-export','report-open','report-copy'].includes(action)){
    if(state.mode!=='personal'||state.role!=='direction')return;
    const report=reportsForCompany(state.reports,state.profile.companyName).find(item=>item.id===state.reportActiveId);if(!report)return;const company=report.companyName||'votre ESN';
    if(action==='report-copy'){
      const copy=globalThis.navigator?.clipboard?.writeText(activityReportEmail(report,company));
      if(!copy){toast('Copie indisponible dans ce navigateur.');return}
      copy.then(()=>toast('Texte copié, aucun e-mail envoyé.'),()=>toast('Copie indisponible dans ce navigateur.'));return;
    }
    const content=action==='report-export'?activityReportCsv(report):activityReportHtml(report,company,location.href.split('#')[0]),mime=action==='report-export'?'text/csv;charset=utf-8':'text/html;charset=utf-8',url=URL.createObjectURL(new Blob([content],{type:mime})),link=document.createElement('a');
    link.href=url;if(action==='report-export')link.download=`bellum-activite-${report.period}-${report.key}.csv`;else{link.target='_blank';link.rel='noopener'}document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast(action==='report-export'?'CSV local téléchargé. Aucun message envoyé.':'Document local ouvert. Aucun message envoyé.');return;
  }
  if(action==='pw-status'){
    if(state.mode!=='personal')return;
    const result=togglePersonalItem(state.personalWorkflows,el.dataset.kind,id);
    if(result.error){toast(result.error);return}
    state.personalWorkflows=result.workflow;render(true);toast(result.message);return;
  }
  if(action==='mode-start-personal'){switchMode('personal');return}
  if(action==='mode-start-scenario'){switchMode('scenario');return}
  if(action==='profile-edit'){
    if(state.mode!=='personal')return;
    state.profileEditing=true;render(true);
    requestAnimationFrame(()=>$('.onboarding-panel')?.scrollIntoView({block:'start',behavior:'smooth'}));return;
  }
  if(action==='goal-edit-focus'){
    if(state.mode!=='personal'||!state.personalWorkflows.goals.some(g=>g.id===id))return;
    focusLocalItem=`local-goal-${id}`;state.teamTab='objectifs';navigate('team','tab=objectifs');return;
  }
  if(action==='agenda-day'){
    if(state.mode!=='personal')return;
    state.agendaDay=val||'';render(true);return;
  }
  if(action==='go-map'||action==='org-open-map'){
    if(state.mode==='choose'){switchMode('personal');return}
    if(state.mode==='scenario'&&state.role!=='direction')return;
    if(state.mode==='scenario'&&state.role==='direction'&&state.city!=='all'){state.mapCity=state.city;state.mapBu=state.bu==='all'?'all':state.bu}
    state.teamTab='administration';state.adminSub='map';navigate('team','tab=administration');return;
  }
  if(action==='org-city'||action==='org-declared-city'){
    if(state.mode!=='personal')return;
    state.orgCity=val;state.orgAgency='all';state.orgUnit='all';state.teamTab='administration';state.adminSub='map';navigate('team','tab=administration');return;
  }
  if(action==='org-agency'){
    if(state.mode!=='personal')return;
    const agency=state.organization.agencies.find(a=>a.id===id);
    if(!agency)return;
    state.orgCity=agency.city;state.orgAgency=id;state.orgUnit='all';state.teamTab='administration';state.adminSub='map';navigate('team','tab=administration');return;
  }
  if(action==='org-edit'){
    if(state.mode!=='personal')return;
    state.orgEditing={kind:el.dataset.kind,id};render(true);
    requestAnimationFrame(()=>$('.org-editor')?.scrollIntoView({block:'center',behavior:'smooth'}));return;
  }
  if(action==='org-cancel-edit'){state.orgEditing=null;render(true);return}
  if(action==='org-archive'||action==='org-restore'){
    if(state.mode!=='personal')return;
    const result=archiveOrganizationItem(state.organization,el.dataset.kind,id,state.role,action==='org-restore');
    if(result.error){toast(result.error);return}
    state.organization=result.org;state.orgEditing=null;
    if(state.orgAgency===id)state.orgAgency='all';
    render(true);toast(result.message);return;
  }
  if(action==='close'){closeDrawer();return}
  if(action==='mobile-toggle'){mobileMenu=!mobileMenu;render(true);return}
  if(action==='parent-nav'){navigate('today');return}
  if(action==='role-picker'){if(state.mode!=='scenario')return;if(mobileMenu){mobileMenu=false;render(true)}const select=$('.topbar [data-change="role"]');select?.focus();try{select?.showPicker()}catch{}return}
  if(action==='day-tab'){state.dayTab=val==='flux'?'flux':'priorites';if(route().name!=='today')navigate('today');else render(true);return}
  if(action==='heatmap-hour'){state.activityHour=val;render(true);return}
  if(action==='clear-activity-hour'){state.activityHour='';render(true);return}
  if(action==='team-tab'){state.teamTab=val;navigate('team',`tab=${val}`);render(false);return}
  if(action==='map-city'){if(state.mode==='scenario'&&state.role==='direction'&&CITIES.some(c=>c.name===val))setMapCity(val);return}
  if(action==='map-bu'){if(state.mode==='scenario'&&state.role==='direction'&&(val==='all'||BUS.some(b=>b.id===val&&b.city===state.mapCity)))setMapBu(val);return}
  if(action==='admin-view'){if(state.mode!=='scenario'||state.role!=='direction')return;state.adminView=['performance','team','affaires','finance'].includes(val)?val:'performance';render(true);return}
  if(action==='city-focus'){state.adminView={deals:'affaires',finance:'finance',team:'team'}[val]||'performance';render(true);requestAnimationFrame(()=>$('#admin-detail')?.scrollIntoView({behavior:'smooth',block:'start'}));return}
  if(action==='deal'||action==='invoice'||action==='member'||action==='bu'||action==='event'||action==='account'){openDrawer(action,id);return}
  if(action==='view-bu'){let b=bu(id);state.city=b.city;state.bu=id;closeToken++;drawer=null;navigate('team',`tab=administration&city=${encodeURIComponent(b.city)}&bu=${id}`);return}
  if(action==='pilot-pipe'){state.pipeStage='';navigate('pilotage','section=pipe');return}
  if(action==='clear-pipe-stage'){state.pipeStage='';render(true);return}
  if(action==='pilot-staffing'){navigate('pilotage','section=staffing');return}
  if(action==='pilot-finance'){navigate('pilotage','section=finance');return}
  if(action==='route-agenda'){navigate('agenda');return}
  if(action==='focus-actions'){$('#priority-actions')?.scrollIntoView({behavior:'smooth',block:'center'});return}
  if(action==='pipe-stage'){state.pipeStage=val;navigate('pilotage','section=pipe');return}
  if(action==='save-outcome'){let d=DEALS.find(x=>x.id===id),type=$(`[data-outcome-id="${id}"]`)?.value,due=$(`[data-outcome-due="${id}"]`)?.value,note=$(`[data-outcome-note="${id}"]`)?.value||'';if(!d||!type||!due||due<todayISO()){toast('Choisissez un résultat et une échéance valide.');return}state.outcomes[id]={type,due,note:note.trim().slice(0,600),label:{rdv:'Rendez-vous planifié',besoin:'Besoin confirmé',reponse:'Réponse reçue',sans_reponse:'Sans réponse'}[type]};render(true);toast('La suite est consignée sur l’affaire et dans le journal.');return}
  if(action==='save-invoice'){let due=$(`[data-invoice-due="${id}"]`)?.value,note=$(`[data-invoice-note="${id}"]`)?.value?.trim();if(!due||due<todayISO()||!note){toast('Ajoutez une date et une note de suivi.');return}state.invoiceNotes[id]={due,note:note.slice(0,600)};render(true);toast('Relance enregistrée dans cet espace. Aucun message envoyé.');return}
}
function handleChange(e){
  if(e.target?.matches?.('[data-finance-salary-mode]')){syncFinanceSalaryMode(e.target.form);return}
  let el=e.target,kind=el.dataset.change,val=el.value;
  if(!kind)return;
  if(kind==='mode'){switchMode(val);return}
  if(kind==='report-period'){if(state.mode!=='personal'||state.role!=='direction')return;state.reportPeriod=['week','month','quarter','semester'].includes(val)?val:'week';state.reportOwner='all';render(true);return}
  if(kind==='report-city'){if(state.mode!=='personal'||state.role!=='direction')return;state.orgCity=val;state.orgAgency='all';state.orgUnit='all';render(true);return}
  if(kind==='report-agency'){if(state.mode!=='personal'||state.role!=='direction')return;state.orgAgency=state.organization.agencies.some(a=>a.id===val&&!a.archivedAt)?val:'all';state.orgUnit='all';render(true);return}
  if(kind==='report-unit'){if(state.mode!=='personal'||state.role!=='direction')return;state.orgUnit=state.organization.units.some(u=>u.id===val&&!u.archivedAt)?val:'all';render(true);return}
  if(kind==='org-city'){
    if(state.mode!=='personal')return;
    state.orgCity=val;state.orgAgency='all';state.orgUnit='all';render(true);return;
  }
  if(kind==='org-agency'){
    if(state.mode!=='personal')return;
    const agency=state.organization.agencies.find(a=>a.id===val);
    state.orgAgency=agency?val:'all';state.orgUnit='all';render(true);return;
  }
  if(kind==='org-unit'){
    if(state.mode!=='personal')return;
    state.orgUnit=state.organization.units.some(u=>u.id===val&&!u.archivedAt)?val:'all';render(true);return;
  }
  if(kind==='role'){if(state.mode!=='scenario')return;state.role=val;state.city='all';state.bu='all';state.pipeStage='';laura.reset();navigate('today');render(false)}
  else if(kind==='city'){state.city=val;state.bu='all';state.pipeStage='';laura.reset();render(true)}
  else if(kind==='bu'){state.bu=val;state.pipeStage='';laura.reset();render(true)}
  else if(kind==='assign-deal'){if(state.role==='sales')return;let d=DEALS.find(d=>d.id===el.dataset.id);if(!d||val&&!bu(d.bu).members.includes(val))return;state.assignments[d.id]=val||null;render(true);toast(val?`${d.account} attribué à ${member(val).name}.`:`${d.account} à répartir.`)}
}
function handleSubmit(e){
  const form=e.target.closest('[data-profile-form],[data-org-form],[data-org-edit],[data-pw-form],[data-plan-form],[data-finance-form]');
  if(!form)return;
  e.preventDefault();
  if(form.dataset.financeForm!==undefined){
    const result=saveFinanceRecord(state.financeRecords,new FormData(form),financeOptions());
    if(result.error){toast(result.error);return}
    state.financeRecords=result.records;state.financeSelectedId=result.record.id;render(true);toast(result.message);return;
  }
  if(form.dataset.planForm!==undefined){
    if(state.mode!=='scenario'||state.role!=='direction')return;
    const data=new FormData(form),raw=name=>String(data.get(name)??'').trim();
    const parse=(name,min,max)=>{const value=raw(name);if(!/^\d+$/.test(value))return null;const number=Number(value);return Number.isSafeInteger(number)&&number>=min&&number<=max?number:null};
    const keys=['weeks','reply','meeting','need','start','emailShare'],filled=keys.filter(key=>raw(key)!=='');
    if(filled.length!==keys.length){toast('Renseignez l’horizon, les quatre taux et la part e-mail.');return}
    const weeks=parse('weeks',1,52),emailShare=parse('emailShare',0,100);
    const rates=Object.fromEntries(['reply','meeting','need','start'].map(key=>[key,parse(key,1,100)]));
    if(weeks===null||emailShare===null||Object.values(rates).some(value=>value===null)){toast('Vérifiez les valeurs : 1 à 52 semaines, taux de 1 à 100 % et part e-mail de 0 à 100 %.');return}
    state.annualPlan={weeks,rates,emailShare};render(true);
    toast('Cadence recalculée avec vos taux.');return;
  }
  if(state.mode!=='personal')return;
  if(form.dataset.profileForm!==undefined){
    const result=readProfile(new FormData(form));
    if(result.error){toast(result.error);return}
    const changedCompany=reportCompanyKey(result.profile.companyName)!==reportCompanyKey(state.profile.companyName);
    if(changedCompany){
      if(reportCompanyKey(state.profile.companyName))state.personalSpaces[spaceKey(state.profile.companyName)]=currentSpace();
      const savedSpace=state.personalSpaces[spaceKey(result.profile.companyName)];
      const nextProfile=normalizeProfile(savedSpace?.profile||emptyProfile());
      for(const key of Object.keys(emptyProfile())){
        if(['firstName','companyName','jobRole'].includes(key))continue;
        if(result.profile[key]!==state.profile[key])nextProfile[key]=result.profile[key];
      }
      const nextRole=result.profile.jobRole===state.profile.jobRole&&savedSpace?.profile?.jobRole?savedSpace.profile.jobRole:result.profile.jobRole;
      state.profile=normalizeProfile({...nextProfile,firstName:result.profile.firstName,companyName:result.profile.companyName,jobRole:nextRole});
      state.organization=normalizeOrganization(savedSpace?.organization||emptyOrganization());
      state.personalWorkflows=normalizeWorkflow(savedSpace?.personalWorkflows||emptyWorkflow());
      state.orgCity=savedSpace?.orgCity||'all';state.orgAgency=savedSpace?.orgAgency||'all';state.orgUnit=savedSpace?.orgUnit||'all';
      state.orgEditing=null;state.agendaDay='';state.activitySeries='all';state.activityDay='';
      state.reportActiveId=null;state.reportPreview=false;state.reportOwner='all';state.reportSeries='all';
    }else state.profile=result.profile;
    state.role=state.profile.jobRole||'sales';
    state.profileEditing=false;
    state.personalWorkflows=applyProfileGoal(state.personalWorkflows,state.profile);
    laura.reset();render(false);toast(`Votre espace local ${state.profile.companyName} est prêt pour ${state.profile.firstName}.`);return;
  }
  if(form.dataset.pwForm){
    const result=createPersonalItem(state.personalWorkflows,form.dataset.pwForm,new FormData(form),state.organization,state.role);
    if(result.error){toast(result.error);return}
    state.personalWorkflows=result.workflow;
    if(form.dataset.pwForm==='goal-edit')focusLocalItem=`local-goal-${new FormData(form).get('id')}`;
    render(true);toast(result.message);return;
  }
  const result=form.dataset.orgEdit
    ?updateOrganizationItem(state.organization,form.dataset.orgEdit,form.dataset.id,new FormData(form),state.role)
    :createOrganizationItem(state.organization,form.dataset.orgForm,new FormData(form),state.role);
  if(result.error){toast(result.error);return}
  state.organization=result.org;
  state.orgEditing=null;
  if(result.city)state.orgCity=result.city;
  if(result.agency){state.orgAgency=result.agency;state.orgCity=state.organization.agencies.find(a=>a.id===result.agency)?.city||state.orgCity}
  render(true);toast(result.message);
}
